    /**
     * Reusable Drag-to-Scroll implementation for wide tables and containers
     */
    window.erpApp.enableDragToScroll = function (element) {
        if (!element) return;

        let isDown = false;
        let startX;
        let scrollLeft;
        let isDragging = false;
        const THRESHOLD = 10; // Ngưỡng di chuyển để xác định là đang kéo (pixels)

        element.addEventListener('mousedown', (e) => {
            // Chỉ xử lý chuột trái
            if (e.button !== 0) return;

            // Không kích hoạt kéo nếu click vào tiêu đề bảng (thead)
            if (e.target.closest('thead')) return;

            isDown = true;
            isDragging = false;
            startX = e.pageX - element.offsetLeft;
            scrollLeft = element.scrollLeft;

            // Không thêm class dragging-active ngay lập tức để tránh nhấp nháy cursor
        });

        element.addEventListener('mouseleave', () => {
            isDown = false;
            element.classList.remove('dragging-active');
        });

        element.addEventListener('mouseup', () => {
            isDown = false;
            element.classList.remove('dragging-active');
            // isDragging sẽ được reset ở mousedown tiếp theo
        });

        element.addEventListener('mousemove', (e) => {
            if (!isDown) return;

            const x = e.pageX - element.offsetLeft;
            const walk = (x - startX);

            // Nếu di chuyển vượt quá ngưỡng, mới coi là đang kéo
            if (Math.abs(walk) > THRESHOLD) {
                if (!isDragging) {
                    isDragging = true;
                    element.classList.add('dragging-active');
                }
                e.preventDefault();
                element.scrollLeft = scrollLeft - walk * 1.5;
            }
        });

        // Chặn sự kiện click nếu người dùng đang thực hiện hành động kéo
        // Sử dụng capture phase (true) để chặn trước khi đến các phần tử con
        element.addEventListener('click', (e) => {
            if (isDragging) {
                e.preventDefault();
                e.stopPropagation();
            }
        }, true);
    };

