    // --- Global Utility Formatters ---
    function formatDate(d) {
        if (!d || d === '—' || d === '-') { return '—'; }
        // Nếu đã là DD/MM/YYYY thì trả về luôn
        if (typeof d === 'string' && /^\d{1,2}\/\d{1,2}\/\d{4}$/.test(d)) return d;

        const date = new Date(d);
        if (isNaN(date.getTime())) { return d; }
        const day = String(date.getDate()).padStart(2, '0');
        const month = String(date.getMonth() + 1).padStart(2, '0');
        const year = date.getFullYear();
        return `${day}/${month}/${year}`;
    }
    window.erpApp.formatDate = formatDate;

    function parseInputDate(d) {
        if (!d) return '';
        if (typeof d !== 'string') return d;
        // Nếu từ input[type=date] (YYYY-MM-DD) -> Chuyển về DD/MM/YYYY
        if (/^\d{4}-\d{2}-\d{2}$/.test(d)) {
            const p = d.split('-');
            return `${p[2]}/${p[1]}/${p[0]}`;
        }
        return d; // Giả định là DD/MM/YYYY hoặc format khác không đổi
    }
    window.erpApp.parseInputDate = parseInputDate;

    /**
     * Chuyển đổi chuỗi ngày (bất kỳ format nào) sang đối tượng Date chuẩn JS để tính toán
     */
    function toJsDate(d) {
        if (!d) return null;
        if (d instanceof Date) return d;
        if (typeof d === 'string') {
            if (/^\d{1,2}\/\d{1,2}\/\d{4}$/.test(d)) {
                const p = d.split('/');
                return new Date(`${p[2]}-${p[1]}-${p[0]}`);
            }
            if (/^\d{4}-\d{2}-\d{2}$/.test(d)) return new Date(d);
        }
        const dt = new Date(d);
        return isNaN(dt.getTime()) ? null : dt;
    }
    window.erpApp.toJsDate = toJsDate;

    function isValidDateString(dStr) {
        if (!dStr) return false;
        if (typeof dStr !== 'string') return false;
        if (!/^\d{1,2}\/\d{1,2}\/\d{4}$/.test(dStr)) return false;
        const parts = dStr.split('/');
        const day = parseInt(parts[0], 10);
        const month = parseInt(parts[1], 10);
        const year = parseInt(parts[2], 10);
        if (isNaN(day) || isNaN(month) || isNaN(year)) return false;
        if (month < 1 || month > 12) return false;
        if (day < 1 || day > 31) return false;
        const date = new Date(year, month - 1, day);
        return date.getFullYear() === year && date.getMonth() === month - 1 && date.getDate() === day;
    }
    window.erpApp.isValidDateString = isValidDateString;

    /**
     * Chuyển đổi sang định dạng YYYY-MM-DD cho input type="date"
     */
    function toInputDate(d) {
        const dt = toJsDate(d);
        if (!dt) return '';
        const year = dt.getFullYear();
        const month = String(dt.getMonth() + 1).padStart(2, '0');
        const day = String(dt.getDate()).padStart(2, '0');
        return `${year}-${month}-${day}`;
    }
    window.erpApp.toInputDate = toInputDate;

