    // --- ONE-TIME DATA MIGRATION: Synchronize pmProjects with contracts and formats ---
    try {
        let pmProjectsChanged = false;
        pmProjects.forEach(project => {
            // Unify all dates to DD/MM/YYYY
            if (project.signingDate) {
                const parsed = formatDate(project.signingDate);
                if (project.signingDate !== parsed) {
                    project.signingDate = parsed;
                    pmProjectsChanged = true;
                }
            }
            if (project.startDate) {
                const parsed = formatDate(project.startDate);
                if (project.startDate !== parsed) {
                    project.startDate = parsed;
                    pmProjectsChanged = true;
                }
            }
            if (project.endDate) {
                const parsed = formatDate(project.endDate);
                if (project.endDate !== parsed) {
                    project.endDate = parsed;
                    pmProjectsChanged = true;
                }
            }

            // Sync missing contract number and signing date from pmContracts or hoSoDocuments
            if (!project.contractNo || !project.signingDate) {
                const mainContract = pmContracts.find(c => c.projectId === project.id) || {};
                if (mainContract.contractNo && !project.contractNo) {
                    project.contractNo = mainContract.contractNo;
                    pmProjectsChanged = true;
                }
                if (mainContract.date && !project.signingDate) {
                    project.signingDate = formatDate(mainContract.date);
                    pmProjectsChanged = true;
                }

                if (!project.contractNo || !project.signingDate) {
                    const mainDoc = hoSoDocuments.find(d => d.type === 'hop-dong-dau-ra' && d.project === project.name) || {};
                    if (mainDoc.title && !project.contractNo) {
                        project.contractNo = mainDoc.title;
                        pmProjectsChanged = true;
                    }
                    if (mainDoc.issueDate && !project.signingDate) {
                        project.signingDate = formatDate(mainDoc.issueDate);
                        pmProjectsChanged = true;
                    }
                }
            }
        });

        if (pmProjectsChanged) {
            localStorage.setItem('erp_pmProjects', JSON.stringify(pmProjects));
            console.log('🚀 DB Synchronization: Synchronized project contracts and unified DD/MM/YYYY format in pmProjects!');
        }

        let congVanListChanged = false;
        congVanList.forEach(cv => {
            if (cv.issueDate) {
                const parsed = formatDate(cv.issueDate);
                if (cv.issueDate !== parsed) {
                    cv.issueDate = parsed;
                    congVanListChanged = true;
                }
            }
        });
        if (congVanListChanged) {
            localStorage.setItem('erp_congVanList', JSON.stringify(congVanList));
            console.log('🚀 DB Synchronization: Unified DD/MM/YYYY format in congVanList!');
        }
    } catch (err) {
        console.error('Error synchronizing database:', err);
    }

    enterpriseInfo = window.enterpriseInfo = loadLocal('enterprise_info', enterpriseInfo);
    if (enterpriseInfo && Array.isArray(enterpriseInfo)) { enterpriseInfo = window.enterpriseInfo = enterpriseInfo[0] || {}; }

