    // ==========================================
    // MAINTENANCE SYNC RECONCILIATION (PM -> VM)
    // ==========================================
    window.erpApp.pmSyncMaintenanceToVm = async () => {
        if (!window.pmMaintenanceLogs || !window.vmMaintenance) { return false; }

        console.log('🔄 Reconciling Maintenance Sync (PM -> VM)...');
        let changed = false;

        window.pmMaintenanceLogs.forEach(log => {
            const exists = window.vmMaintenance.find(m => m.id === log.id);
            if (!exists) {
                // Better matching: try equipmentId, code, or vId
                const eq = (window.pmEquipment || []).find(e => e.id === log.equipmentId || e.code === log.equipmentId || e.id === log.vId);
                const project = (window.pmProjects || []).find(p => p.id === log.projectId);

                // Determine the correct vId for VM module (prioritize TB-xxx codes)
                let vId = log.vId || (eq ? eq.code : log.equipmentId);
                if (vId && !vId.startsWith('TB-') && eq && eq.code) { vId = eq.code; }

                if (vId) {
                    const vmLog = {
                        id: log.id,
                        vId: vId,
                        desc: log.content,
                        projectName: project ? project.name : (log.projectName || 'Dự án (N/A)'),
                        type: log.type || 'Bảo trì',
                        date: (log.date && log.date.includes('-')) ? log.date.split('-').reverse().join('/') : (log.date || ''),
                        odo: log.odo || 0,
                        cost: log.cost || 0,
                        status: 'Hoàn thành'
                    };
                    window.vmMaintenance.push(vmLog);
                    changed = true;
                    if (window.CrudSync) { window.CrudSync.saveItem('vmMaintenance', vmLog, 'id'); }
                }
            } else {
                // Update projectName if it was missing or default
                const project = (window.pmProjects || []).find(p => p.id === log.projectId);
                if (project && (!exists.projectName || exists.projectName === 'Dự án (N/A)')) {
                    exists.projectName = project.name;
                    changed = true;
                    if (window.CrudSync) { window.CrudSync.saveItem('vmMaintenance', exists, 'id'); }
                }
            }
        });

        if (changed) {
            localStorage.setItem('erp_vmMaintenance', JSON.stringify(window.vmMaintenance));
            console.log('✅ Maintenance reconciliation complete.');
            return true;
        }
        return false;
    };

