    // 🛡️ DATA INTEGRITY: Force immediate cleanup of legacy equipment data on load
    // This prevents old "MX-", "MU-", etc. from appearing even after F5
    (function sanitizeData() {
        try {
            const oldPrefixes = ['MX-', 'MU-', 'XL-', 'CT-'];
            const isOld = (s) => s && oldPrefixes.some(p => String(s).startsWith(p)) && !String(s).startsWith('TB-') && !String(s).startsWith('VX-');

            // 1. Cleanup Master Vehicle Module
            if (Array.isArray(vmVehicles)) {
                const cleanedVM = vmVehicles.filter(v => v.context !== 'equipment' || !isOld(v.id));
                if (cleanedVM.length !== vmVehicles.length) {
                    vmVehicles = window.vmVehicles = cleanedVM;
                    localStorage.setItem('erp_vmVehicles', JSON.stringify(vmVehicles));
                }
            }

            // 2. Cleanup Project Management Module
            if (Array.isArray(pmEquipment) && Array.isArray(vmVehicles)) {
                const vmIds = vmVehicles.map(v => v.id);
                const filteredPmEq = pmEquipment.filter(e => vmIds.includes(e.code) && !isOld(e.code));
                if (filteredPmEq.length !== pmEquipment.length) {
                    pmEquipment = window.pmEquipment = filteredPmEq;
                    localStorage.setItem('erp_pmEquipment', JSON.stringify(pmEquipment));
                }
            }

            // 3. Cleanup Master Registry
            if (Array.isArray(masterEquipmentRegistry) && Array.isArray(vmVehicles)) {
                const vmIds = vmVehicles.map(v => v.id);
                const filteredMaster = masterEquipmentRegistry.filter(e => vmIds.includes(e.code) && !isOld(e.code));
                if (filteredMaster.length !== masterEquipmentRegistry.length) {
                    masterEquipmentRegistry = window.masterEquipmentRegistry = filteredMaster;
                    localStorage.setItem('erp_masterEquipmentRegistry', JSON.stringify(masterEquipmentRegistry));
                }
            }
            console.log('🛡️ System Data Sanitized: Legacy equipment purged.');
        } catch (e) { console.warn('Sanitization failed', e); }
    })();

