    // ==========================================
    // Numeric Utilities (vi-VN Localization)
    // ==========================================
    const viFmt = new Intl.NumberFormat('vi-VN');

    /**
     * Formats a numeric value for display using vi-VN locale (dot as thousand separator)
     * @param {number|string} val - The value to format
     * @returns {string} Formatted string
     */
    window.erpApp.formatValue = function (val, options = {}) {
        if (val === undefined || val === null || isNaN(val)) { return '0'; }
        if (Object.keys(options).length > 0) {
            return new Intl.NumberFormat('vi-VN', options).format(parseFloat(val));
        }
        return viFmt.format(parseFloat(val));
    };

    /**
     * Parses a localized numeric string (with dots as separators) back to a raw number
     * @param {string} str - The formatted string (e.g., "1.500.000")
     * @returns {number} Raw number (e.g., 1500000)
     */
    window.erpApp.parseVND = function (str) {
        if (!str) { return 0; }
        if (typeof str === 'number') { return str; }
        const clean = str.toString().replace(/\./g, '').replace(/,/g, '.').replace(/[^\d.]/g, '');
        const num = parseFloat(clean);
        return isNaN(num) ? 0 : num;
    };

    /**
     * Sanitizes an input string for storage by removing all non-numeric characters except decimals
     * @param {string} str 
     * @returns {number}
     */
    window.erpApp.cleanNum = function (str) {
        return window.erpApp.parseVND(str);
    };

    /**
     * Event handler for real-time numeric input formatting (oninput)
     * @param {HTMLInputElement} input 
     */
    window.erpApp.formatNumberInput = function (input) {
        let cursorPosition = input.selectionStart;
        let originalLength = input.value.length;

        let val = input.value.replace(/\D/g, '');
        if (val === '') {
            input.value = '';
            return;
        }

        const formatted = viFmt.format(parseInt(val));
        input.value = formatted;

        // Adjust cursor position to handle added dots
        let newLength = input.value.length;
        cursorPosition = cursorPosition + (newLength - originalLength);
        input.setSelectionRange(cursorPosition, cursorPosition);
    };

    const IMG_LOADING = 'data:image/svg+xml,%3Csvg%20width%3D%22800%22%20height%3D%22600%22%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%3E%3Crect%20width%3D%22100%25%22%20height%3D%22100%25%22%20fill%3D%22%23f1f5f9%22%2F%3E%3Ctext%20x%3D%2250%25%22%20y%3D%2250%25%22%20font-family%3D%22Arial%2C%20sans-serif%22%20font-size%3D%2224%22%20fill%3D%22%2364748b%22%20text-anchor%3D%22middle%22%20dy%3D%22.3em%22%3E%C4%90ang%20t%E1%BA%A3i...%3C%2Ftext%3E%3C%2Fsvg%3E';
    const IMG_ERROR = 'https://placehold.co/600x400/f1f5f9/64748b?text=Loi+anh';

    /**
     * Proactively resolves sharing links (Google Photos/Drive) to direct image URLs
     * @param {HTMLImageElement} imgEl 
     * @param {string} url 
     */
    window.erpApp.resolveSharingLink = async function (imgEl, url) {
        if (!imgEl || !url || imgEl.dataset.resolved === 'true') { return; }

        const isSharingLink = url.includes('photos.app.goo.gl') ||
            url.includes('photos.google.com') ||
            (url.includes('drive.google.com') && !url.includes('uc?'));

        if (!isSharingLink) { return; }

        imgEl.dataset.resolved = 'true';
        imgEl.src = IMG_LOADING;

        const tryProxy = async (proxyBase, timeout = 5000) => {
            const controller = new AbortController();
            const timeoutId = setTimeout(() => controller.abort(), timeout);

            try {
                const proxyUrl = `${proxyBase}${encodeURIComponent(url)}`;
                const response = await fetch(proxyUrl, { signal: controller.signal });
                clearTimeout(timeoutId);

                if (!response.ok) { throw new Error('Proxy error'); }

                const html = await response.text();
                const ogMatch = html.match(/<meta[^>]+property=["']og:image["'][^>]+content=["']([^"']+)["']/i) ||
                    html.match(/<meta[^>]+content=["']([^"']+)["'][^>]+property=["']og:image["']/i);

                if (ogMatch && ogMatch[1]) { return ogMatch[1]; }
                throw new Error('No og:image found');
            } catch (e) {
                clearTimeout(timeoutId);
                throw e;
            }
        };

        // Faster proxies first
        const proxies = [
            'https://corsproxy.io/?',
            'https://api.allorigins.win/raw?url=',
            'https://api.codetabs.com/v1/proxy?quest=',
            'https://thingproxy.freeboard.io/fetch/'
        ];

        try {
            // Try all proxies in parallel and take the first successful one
            const imageUrl = await Promise.any(proxies.map(p => tryProxy(p)));

            if (imageUrl) {
                imgEl.src = `https://images.weserv.nl/?url=${encodeURIComponent(imageUrl)}&w=800&output=webp&q=80`;
                imgEl.title = 'Đã giải mã thành công.';
            }
        } catch (e) {
            console.error('All proxies failed to resolve Google Photos link', e);
            imgEl.src = IMG_ERROR;
            imgEl.title = 'Không thể giải mã link ảnh. Vui lòng kiểm tra link chia sẻ.';
        }
    };

    /**
     * Logic chuẩn hóa để tạo một đối tượng dự án mới trong hệ thống
     * @param {string} projName 
     * @returns {object}
     */
    window.erpApp.createNewProjectObject = function (projName) {
        const pmProjects = window.pmProjects || [];
        const maxPmId = Math.max(...pmProjects.map(p => {
            const num = parseInt((p.id || '').replace('PJ-', ''), 10);
            return isNaN(num) ? 0 : num;
        }), 0);

        return {
            id: 'PJ-' + String(maxPmId + 1).padStart(3, '0'),
            name: projName,
            client: 'Chưa cập nhật',
            manager: 'Chưa cập nhật',
            budget: 0,
            revenue: '0',
            progress: 0,
            startDate: new Date().toISOString().split('T')[0],
            endDate: new Date().toISOString().split('T')[0],
            status: 'dang-thi-cong',
            type: 'Khác',
            contractNo: '',
            signingDate: '',
            location: 'Chưa cập nhật'
        };
    };

    /**
     * Hiển thị dialog chuyên nghiệp để thêm dự án mới (thay thế prompt)
     * @param {function} callback - Hàm gọi lại khi dự án được xác nhận
     * @param {function} onCancel - Hàm gọi lại khi người dùng hủy
     */
    window.erpApp.showAddProjectDialog = function (callback, onCancel) {
        const modalId = 'add-project-modal-' + Date.now();
        const modal = document.createElement('div');
        modal.className = 'modal-overlay';
        modal.id = modalId;
        modal.innerHTML = `
            <div class="modal-content modal-mini">
                <div class="modal-header">
                    <h2 style="display:flex;align-items:center;gap:10px">
                        <span class="material-icons-outlined" style="color:var(--primary);font-size:24px">add_business</span>
                        Thêm dự án mới
                    </h2>
                    <button class="close-btn" id="${modalId}-close">&times;</button>
                </div>
                <div class="modal-body">
                    <div class="form-group">
                        <label>Tên dự án/công trình <span class="required">*</span></label>
                        <input type="text" id="${modalId}-input" placeholder="VD: Sửa chữa cầu Tràng Tiền..." autofocus autocomplete="off">
                        <div id="${modalId}-error" style="color:var(--icon-red); font-size:11.5px; margin-top:6px; display:none; align-items:center; gap:4px">
                            <span class="material-icons-outlined" style="font-size:14px">error_outline</span>
                            <span></span>
                        </div>
                    </div>
                </div>
                <div class="modal-footer">
                    <button class="btn-cancel" id="${modalId}-cancel">Bỏ qua</button>
                    <button class="btn-save" id="${modalId}-save">
                        <span class="material-icons-outlined">check_circle</span>
                        Xác nhận thêm
                    </button>
                </div>
            </div>
        `;
        document.body.appendChild(modal);

        const input = document.getElementById(`${modalId}-input`);
        const saveBtn = document.getElementById(`${modalId}-save`);
        const cancelBtn = document.getElementById(`${modalId}-cancel`);
        const closeBtn = document.getElementById(`${modalId}-close`);
        const errorEl = document.getElementById(`${modalId}-error`);

        const showError = (msg) => {
            errorEl.querySelector('span:last-child').textContent = msg;
            errorEl.style.display = 'flex';
            input.style.borderColor = 'var(--icon-red)';
            input.focus();
        };

        const handleClose = () => {
            modal.classList.add('closing');
            setTimeout(() => {
                modal.remove();
                if (onCancel) { onCancel(); }
            }, 200);
        };

        const handleSave = () => {
            const val = input.value.trim();
            if (!val) {
                showError('Vui lòng nhập tên dự án');
                return;
            }

            // Duplicate check
            const projects = window.pmProjects || [];
            if (projects.some(p => p.name.toLowerCase() === val.toLowerCase())) {
                showError('Tên dự án này đã tồn tại trong hệ thống');
                return;
            }

            modal.classList.add('closing');
            setTimeout(() => {
                modal.remove();
                callback(val);
            }, 200);
        };

        saveBtn.onclick = handleSave;
        cancelBtn.onclick = handleClose;
        closeBtn.onclick = handleClose;

        input.oninput = () => {
            errorEl.style.display = 'none';
            input.style.borderColor = '';
        };

        input.onkeydown = (e) => {
            if (e.key === 'Enter') { handleSave(); }
            if (e.key === 'Escape') { handleClose(); }
        };

        setTimeout(() => input.focus(), 150);
    };

    window.erpApp.resolveFileUrl = function (url, forImage = false) {
        if (!url) { return ''; }
        url = url.trim();
        const apiBase = window.API_BASE_URL || window.PROD_API_URL || 'https://quanlycongty.onrender.com';

        if (url.includes('drive.google.com') && url.includes('/file/d/')) {
            try {
                const fileId = url.split('/file/d/')[1].split('/')[0];
                if (forImage) {
                    return `${apiBase}/api/drive/view/${fileId}`;
                } else {
                    return `https://drive.google.com/file/d/${fileId}/view?usp=drivesdk`;
                }
            } catch (e) { return url; }
        }

        if (url.startsWith('/api/')) {
            return `${apiBase}${url}`;
        }

        return url;
    };

    window.erpApp.transformImageUrl = function (url) {
        if (!url) { return IMG_ERROR; }
        return window.erpApp.resolveFileUrl(url, true);
    };


    /**
     * Handles image loading errors by attempting to resolve common sharing link issues
     * @param {HTMLImageElement} imgEl 
     * @param {string} originalUrl 
     */
    window.erpApp.handleImageError = async function (imgEl, originalUrl) {
        if (!imgEl || !originalUrl) { return; }

        // Prevent infinite retry loops
        const retryCount = parseInt(imgEl.dataset.retryCount || '0');
        if (retryCount >= 3) {
            imgEl.src = IMG_ERROR;
            imgEl.title = 'Không thể tải hình ảnh. Kiểm tra lại đường dẫn.';
            return;
        }

        imgEl.dataset.retryCount = retryCount + 1;

        const isSharingLink = originalUrl.includes('photos.app.goo.gl') ||
            originalUrl.includes('photos.google.com') ||
            originalUrl.includes('/share/') ||
            (originalUrl.includes('drive.google.com') && !originalUrl.includes('uc?'));

        if (isSharingLink) {
            // Reset resolved flag to allow re-resolution
            imgEl.dataset.resolved = 'false';
            imgEl.dataset.retried = 'true';

            // Add small delay before retrying
            await new Promise(resolve => setTimeout(resolve, 500));
            window.erpApp.resolveSharingLink(imgEl, originalUrl);
        } else {
            imgEl.src = IMG_ERROR;
            imgEl.title = 'Không thể tải hình ảnh từ URL này.';
        }
    };

    /**
     * Specialized formatter for quantities that allows decimals (comma)
     */
    window.erpApp.formatQuantityInput = function (input) {
        let cursorPosition = input.selectionStart;
        let originalLength = input.value.length;

        // Allow digits and one comma
        let val = input.value.replace(/[^\d,]/g, '');

        // Handle multiple commas by only keeping the first one
        const parts = val.split(',');
        if (parts.length > 2) {
            val = parts[0] + ',' + parts.slice(1).join('');
        }

        if (val === '') {
            input.value = '';
            return;
        }

        // Format integer part with dots
        let integerPart = parts[0].replace(/\D/g, '');
        let decimalPart = parts[1] !== undefined ? ',' + parts[1].replace(/\D/g, '') : '';

        if (integerPart === '' && decimalPart !== '') { integerPart = '0'; }

        const formattedInt = integerPart !== '' ? viFmt.format(parseInt(integerPart)) : '';
        input.value = formattedInt + decimalPart;

        // Adjust cursor position
        let newLength = input.value.length;
        cursorPosition = cursorPosition + (newLength - originalLength);
        input.setSelectionRange(cursorPosition, cursorPosition);
    };
    window.erpApp.formatVNDInput = window.erpApp.formatNumberInput; // Alias for backward compatibility



    /**
     * Tự động quét "Lưu trữ hồ sơ" và tạo dự án trong "Quản lý dự án" nếu chưa có
     */
    window.erpApp.pmReconcileArchiveProjects = async function () {
        if (typeof hoSoDocuments === 'undefined' || typeof pmProjects === 'undefined') { return; }

        console.log('🔍 [PM Reconcile] Checking for projects in Archive missing from Project Management...');

        // Lấy danh sách tên dự án duy nhất từ Archive
        const archiveProjectNames = [...new Set(hoSoDocuments.map(d => d.project).filter(p => p && p !== 'Không thuộc dự án'))];
        const pmProjectNames = new Set(pmProjects.map(p => p.name));

        const missingNames = archiveProjectNames.filter(name => !pmProjectNames.has(name));

        if (missingNames.length > 0) {
            console.log(`🚀 [PM Reconcile] Found ${missingNames.length} projects to sync:`, missingNames);

            for (const name of missingNames) {
                const newProject = window.erpApp.createNewProjectObject(name);
                const docs = hoSoDocuments.filter(d => d.project === name);
                if (docs.length > 0) {
                    const mainDoc = docs.find(d => d.category === 'hop-dong-dau-ra') ||
                        docs.find(d => d.category === 'hop-dong') ||
                        docs[0];
                    if (mainDoc) {
                        if (mainDoc.customer && mainDoc.customer !== 'VIETBACHCORP') {
                            newProject.client = mainDoc.customer;
                        } else if (mainDoc.supplier && mainDoc.supplier !== 'VIETBACHCORP') {
                            newProject.client = mainDoc.supplier;
                        }
                        if (mainDoc.value) newProject.budget = parseFloat(mainDoc.value) || 0;
                        if (mainDoc.issueDate) newProject.startDate = mainDoc.issueDate;
                        if (mainDoc.contractNo) newProject.contractNo = mainDoc.contractNo;
                        if (mainDoc.issueDate) newProject.signingDate = mainDoc.issueDate;
                    }
                }
                pmProjects.push(newProject);

                // Đồng bộ lên Cloud
                if (window.CrudSync) {
                    await window.CrudSync.saveItem('pmProjects', newProject, 'id');
                }
            }

            // Cập nhật local storage
            localStorage.setItem('erp_pmProjects', JSON.stringify(pmProjects));

            if (typeof window.erpApp.showToast === 'function') {
                window.erpApp.showToast(`Đã tự động đồng bộ ${missingNames.length} dự án từ kho Lưu trữ hồ sơ.`, 'success');
            } else if (typeof showToast === 'function') {
                showToast(`Đã tự động đồng bộ ${missingNames.length} dự án từ kho Lưu trữ hồ sơ.`, 'success');
            }
        }

        // 2. Reconcile Contracts
        let contractReconciledCount = 0;
        hoSoDocuments.forEach(doc => {
            const isContract = ['hop-dong-dau-ra', 'hop-dong-dau-vao'].includes(doc.category);
            if (!isContract) { return; }

            // Find matching project in PM
            const linkedProject = pmProjects.find(p => p.name === doc.project);
            if (!linkedProject) { return; }

            // Check if contract already exists in PM
            const existingContract = pmContracts.find(c => c.linkedHsId === doc.id || (c.contractNo === doc.contractNo && c.projectId === linkedProject.id));
            if (!existingContract) {
                console.log(`🚀 [PM Reconcile] Mirroring contract ${doc.title} from Archive to PM`);
                const newContract = {
                    id: 'PMC-' + Date.now() + '-' + Math.floor(Math.random() * 1000),
                    projectId: linkedProject.id,
                    title: doc.title,
                    partner: doc.partner || 'Đối tác chưa xác định',
                    value: parseFloat(doc.value) || 0,
                    contractNo: doc.contractNo || doc.id,
                    type: doc.category === 'hop-dong-dau-ra' ? 'outbound' : 'inbound',
                    category: doc.category === 'hop-dong-dau-ra' ? 'thi-cong' : 'thau-phu',
                    status: 'moi-ki',
                    date: doc.date || new Date().toISOString().split('T')[0],
                    linkedHsId: doc.id,
                    sync: true
                };
                pmContracts.push(newContract);
                contractReconciledCount++;

                // Cloud Sync
                if (window.CrudSync) {
                    window.CrudSync.saveItem('pmContracts', newContract, 'id');
                }
            }
        });

        if (contractReconciledCount > 0) {
            console.log(`🚀 [PM Reconcile] Mirrored ${contractReconciledCount} contracts.`);
            localStorage.setItem('erp_pmContracts', JSON.stringify(pmContracts));
        }
    };

