    window.erpApp.saveEditProfile = function () {
        const form = document.getElementById('editProfileForm');
        const btn = document.getElementById('btnSaveProfile');
        if (!form || !btn) { return; }

        const formData = new FormData(form);
        const currentProfile = window.getProfileData();

        // Cập nhật các trường có trong form
        const updatedData = { ...currentProfile };
        formData.forEach((value, key) => {
            updatedData[key] = value;
        });

        // Loading state
        btn.disabled = true;
        btn.innerHTML = '<span class="material-icons-outlined animate-spin" style="font-size:16px; vertical-align:middle; margin-right:8px;">sync</span> Đang lưu...';

        setTimeout(() => {
            window.saveProfileData(updatedData);
            window.erpApp.closeEditProfile();
            showToast('Thông tin hồ sơ đã được cập nhật thành công!', 'success');

            // Gửi thông báo hệ thống
            addSystemNotification(
                'Đã cập nhật thông tin hồ sơ cá nhân',
                'manage_accounts',
                'blue',
                { page: 'ho-so-ca-nhan' }
            );

            if (window.erpApp.getCurrentPage() === 'ho-so-ca-nhan') {
                renderProfilePage();
            }
        }, 600);
    };

    window.erpApp.closeEditProfile = function () {
        const modal = document.getElementById('editProfileModal');
        if (modal) { modal.remove(); }
    };

    // ==========================================
    // Login & UI Persistence
    // ==========================================
    function initLogin() {
        const loginScreen = document.getElementById('loginScreen');
        const appContainer = document.getElementById('appContainer');
        const loginForm = document.getElementById('loginForm');
        const loginError = document.getElementById('loginError');
        const togglePasswordBtn = document.getElementById('togglePassword');
        const passwordInput = document.getElementById('loginPassword');
        const usernameInput = document.getElementById('loginUsername');
        const loginBtn = document.getElementById('loginBtn');
        const rememberMe = document.getElementById('rememberMe');

        if (!loginScreen || !appContainer) {
            return;
        }

        // Auto-login if session exists - DISABLED
        const handleLogin = (e) => {
            if (e) { e.preventDefault(); e.stopPropagation(); }

            if (loginError) {
                loginError.textContent = '';
                loginError.style.display = 'none';
            }

            const username = usernameInput ? usernameInput.value.trim().toLowerCase() : '';
            const password = passwordInput ? passwordInput.value.trim() : '';

            if (!username || !password) {
                showError('Vui lòng nhập đầy đủ tài khoản và mật khẩu.');
                return;
            }

            if (loginBtn) {
                loginBtn.classList.add('loading');
                loginBtn.innerHTML = '<span class="material-icons-outlined animate-spin" style="font-size:18px">sync</span> Đang kiểm tra...';
                loginBtn.disabled = true;
            }

            // Lấy thêm user từ DB local
            let dbUsers = [];
            try { dbUsers = JSON.parse(localStorage.getItem('erp_users_db')) || []; } catch (err) { }
            let regUsers = [];
            try { regUsers = JSON.parse(localStorage.getItem('erp_registered_users')) || []; } catch (err) { }

            const approvedRegUsers = regUsers.filter(u => u.status === 'approved');
            const extraDbUsers = dbUsers.filter(u => u.role !== 'Admin'); // Không cho phép fake admin từ localDB

            const allUsers = [...users, ...extraDbUsers, ...approvedRegUsers];
            console.log('Total users to check:', allUsers.length);

            setTimeout(() => {
                console.log('Searching for user...');
                const user = allUsers.find(u => (u.username.toLowerCase() === username || (u.email && u.email.toLowerCase() === username)) && u.password === password);

                if (!user) {
                    console.warn('User not found or password incorrect');
                    showError('Tài khoản hoặc mật khẩu không chính xác.');
                    resetBtn();
                    return;
                }

                // Check approval status for registered users
                if (user.status && user.status === 'pending') {
                    showError('Tài khoản đang chờ Admin phê duyệt.');
                    resetBtn();
                    return;
                }
                if (user.status && user.status === 'rejected') {
                    showError('Tài khoản đã bị từ chối. Liên hệ quản trị viên.');
                    resetBtn();
                    return;
                }

                currentUser = { ...user };
                sessionStorage.setItem('erp_user', JSON.stringify(currentUser));

                if (document.getElementById('rememberMe') && document.getElementById('rememberMe').checked) {
                    localStorage.setItem('erp_remembered_user', username);
                    localStorage.setItem('erp_remembered_pass', password);
                } else {
                    localStorage.removeItem('erp_remembered_user');
                    localStorage.removeItem('erp_remembered_pass');
                }

                loginScreen.style.animation = 'fadeOut 0.3s ease forwards';
                setTimeout(() => {
                    try {
                        loginScreen.style.display = 'none';
                        loginScreen.classList.add('hidden');
                        loginScreen.style.animation = '';
                        appContainer.style.display = 'flex';
                        updateUserUI();

                        // Record session & Notify
                        const now = new Date();
                        const timeStr = `${String(now.getHours()).padStart(2, '0')}:${String(now.getMinutes()).padStart(2, '0')} - ${String(now.getDate()).padStart(2, '0')}/${String(now.getMonth() + 1).padStart(2, '0')}/${now.getFullYear()}`;

                        const newSession = {
                            id: 'S' + Date.now(),
                            account: user.fullName,
                            email: user.email || (user.username + '@company.vn'),
                            device: /Mobile|Android|iPhone/i.test(navigator.userAgent) ? 'Mobile' : 'Windows PC',
                            os: navigator.platform,
                            browser: 'Chrome', // Simplified
                            ip: '127.0.0.1',
                            location: 'Việt Nam',
                            lastLogin: timeStr,
                            status: 'current'
                        };

                        // Update other sessions to active
                        if (Array.isArray(systemSessions)) {
                            systemSessions.forEach(s => { if (s.status === 'current') { s.status = 'active'; } });
                            systemSessions.unshift(newSession);
                            if (systemSessions.length > 20) { systemSessions.pop(); }
                            localStorage.setItem('erp_sessions', JSON.stringify(systemSessions));
                        }

                        // addSystemNotification(
                        //     `Đăng nhập thành công: ${user.fullName} (${newSession.device})`,
                        //     'login',
                        //     'blue',
                        //     { page: 'he-thong', module: 'Thiết bị đăng nhập' }
                        // );

                        if (typeof navigateTo === 'function') { navigateTo('trang-chu'); }
                        if (window.erpApp && typeof window.erpApp.updateSidebarVisibility === 'function') {
                            window.erpApp.updateSidebarVisibility();
                        }
                    } catch (transitionErr) {
                        console.error('Error during login transition:', transitionErr);
                        showError('Có lỗi xảy ra trong quá trình chuyển hướng. Vui lòng tải lại trang.');
                        resetBtn();
                    }
                }, 300);
            }, 600);

            function showError(msg) {
                if (loginError) {
                    loginError.innerHTML = `<span class="material-icons-outlined" style="font-size:15px">error</span> ${msg}`;
                    loginError.style.display = 'flex';
                    loginError.style.animation = 'shake 0.4s ease';
                }
            }
            function resetBtn() {
                if (loginBtn) {
                    loginBtn.classList.remove('loading');
                    loginBtn.innerHTML = '<span class="material-icons-outlined">login</span> Đăng nhập';
                    loginBtn.disabled = false;
                }
            }
        };

        // Wire up buttons and form
        if (loginBtn) { loginBtn.onclick = handleLogin; }
        if (loginForm) { loginForm.onsubmit = handleLogin; }

        const handleEnterKey = (e) => {
            if (e.key !== 'Enter' && e.code !== 'NumpadEnter') { return; }
            if (usernameInput && passwordInput && usernameInput.value.trim() && passwordInput.value.trim()) {
                e.preventDefault();
                handleLogin(e);
            }
        };

        if (loginForm) { loginForm.addEventListener('keydown', handleEnterKey); }
        if (usernameInput) { usernameInput.addEventListener('keydown', handleEnterKey); }
        if (passwordInput) { passwordInput.addEventListener('keydown', handleEnterKey); }
        document.addEventListener('keydown', (e) => {
            if (!loginScreen || loginScreen.style.display === 'none') { return; }
            handleEnterKey(e);
        });

        if (togglePasswordBtn && passwordInput) {
            togglePasswordBtn.onclick = (e) => {
                e.preventDefault(); e.stopPropagation();
                const isPassword = passwordInput.type === 'password';
                passwordInput.type = isPassword ? 'text' : 'password';
                togglePasswordBtn.querySelector('.material-icons-outlined').textContent = isPassword ? 'visibility' : 'visibility_off';
            };
        }

        // Fill remembered user
        let remembered = localStorage.getItem('erp_remembered_user');
        let rememberedPass = localStorage.getItem('erp_remembered_pass');
        if (remembered && usernameInput) {
            usernameInput.value = remembered;
            if (rememberMe) {
                rememberMe.checked = true;
                // If remembered, show the password by default as requested
                if (passwordInput && rememberedPass) {
                    passwordInput.value = rememberedPass;
                    passwordInput.type = 'text';
                    if (togglePasswordBtn) {
                        const icon = togglePasswordBtn.querySelector('.material-icons-outlined');
                        if (icon) { icon.textContent = 'visibility'; }
                    }
                }
            }
            if (passwordInput && !rememberedPass) { passwordInput.focus(); }
        }

        // Toggle password visibility when Remember Me is checked/unchecked
        if (rememberMe && passwordInput) {
            rememberMe.addEventListener('change', () => {
                if (rememberMe.checked) {
                    passwordInput.type = 'text';
                    if (togglePasswordBtn) {
                        const icon = togglePasswordBtn.querySelector('.material-icons-outlined');
                        if (icon) { icon.textContent = 'visibility'; }
                    }
                } else {
                    passwordInput.type = 'password';
                    if (togglePasswordBtn) {
                        const icon = togglePasswordBtn.querySelector('.material-icons-outlined');
                        if (icon) { icon.textContent = 'visibility_off'; }
                    }
                }
            });
        }

        // Initialize notification badge
        if (typeof updateNotificationBadge === 'function') { updateNotificationBadge(); }

        // Fallback Force Login
        window.erpApp.forceLogin = function () {
            usernameInput.value = 'admin';
            passwordInput.value = 'quoclachu';
            handleLogin();
        };

        // ==========================================
        // Toggle Login / Register Forms
        // ==========================================
        const showRegisterBtn = document.getElementById('showRegisterBtn');
        const showLoginBtn = document.getElementById('showLoginBtn');
        const registerFormEl = document.getElementById('registerForm');

        if (showRegisterBtn) {
            showRegisterBtn.onclick = (e) => {
                e.preventDefault();
                loginForm.style.display = 'none';
                registerFormEl.style.display = 'flex';
                registerFormEl.style.animation = 'fadeInUp 0.4s ease both';
            };
        }
        if (showLoginBtn) {
            showLoginBtn.onclick = (e) => {
                e.preventDefault();
                registerFormEl.style.display = 'none';
                loginForm.style.display = 'flex';
                loginForm.style.animation = 'fadeInUp 0.4s ease both';
            };
        }

        // ==========================================
        // Registration Handler
        // ==========================================
        const registerBtn = document.getElementById('registerBtn');
        const registerError = document.getElementById('registerError');

        if (registerBtn) {
            registerBtn.onclick = function () {
                const fullName = document.getElementById('regFullName').value.trim();
                const username = document.getElementById('regUsername').value.trim();
                const email = document.getElementById('regEmail').value.trim();
                const pw = document.getElementById('regPassword').value;
                const pw2 = document.getElementById('regConfirmPassword').value;
                const dept = document.getElementById('regDepartment').value;

                if (registerError) { registerError.textContent = ''; registerError.style.display = 'none'; }

                if (!fullName || !username || !email || !pw) {
                    showRegError('Vui lòng nhập đầy đủ thông tin.');
                    return;
                }
                if (pw.length < 6) { showRegError('Mật khẩu tối thiểu 6 ký tự.'); return; }
                if (pw !== pw2) { showRegError('Mật khẩu xác nhận không khớp.'); return; }

                let regUsers = [];
                try { regUsers = JSON.parse(localStorage.getItem('erp_registered_users')) || []; } catch (e) { }

                if (regUsers.find(u => u.username === username)) {
                    showRegError('Tên đăng nhập này đã được sử dụng.');
                    return;
                }
                if (regUsers.find(u => u.email === email)) {
                    showRegError('Email này đã được đăng ký.');
                    return;
                }

                const initials = fullName.split(' ').map(w => w[0]).join('').substring(0, 2).toUpperCase();
                const newUser = {
                    id: 'REG_' + Date.now(),
                    username: username,
                    email: email,
                    fullName: fullName,
                    password: pw,
                    role: 'Nhân viên',
                    department: dept || 'Chưa phân bổ',
                    initials: initials,
                    status: 'pending',
                    permissions: ['trang-chu', 'ban-quyen'],
                    provider: 'email',
                    createdAt: new Date().toISOString(),
                    approvedBy: null
                };

                regUsers.push(newUser);
                localStorage.setItem('erp_registered_users', JSON.stringify(regUsers));
                if (window.CrudSync) { window.CrudSync.saveItem('erp_registered_users', newUser, 'username'); }

                if (registerError) {
                    registerError.className = 'login-success';
                    registerError.innerHTML = '<span class="material-icons-outlined" style="font-size:16px">check_circle</span> Đăng ký thành công! Tài khoản đang chờ Admin phê duyệt.';
                    registerError.style.display = 'flex';
                }

                document.getElementById('regFullName').value = '';
                document.getElementById('regUsername').value = '';
                document.getElementById('regEmail').value = '';
                document.getElementById('regPassword').value = '';
                document.getElementById('regConfirmPassword').value = '';

                addSystemNotification(
                    'Tài khoản mới đăng ký: ' + fullName + ' (' + email + ')',
                    'user-register', 'purple',
                    { page: 'he-thong', module: 'Quản lý tài khoản' }
                );
            };
        }

        function showRegError(msg) {
            if (registerError) {
                registerError.className = 'login-error';
                registerError.innerHTML = '<span class="material-icons-outlined" style="font-size:15px">error</span> ' + msg;
                registerError.style.display = 'flex';
            }
        }

        // ==========================================
        // Google Sign-In (Firebase Auth)
        // ==========================================
        function handleGoogleAuth() {
            if (!window.auth) {
                showToast('Tính năng Đăng nhập Google chưa được kích hoạt.\n\nVui lòng liên hệ Admin để bật Firebase Authentication trong hệ thống.\n\nHoặc dùng tài khoản/mật khẩu để đăng nhập.', 'warning');
                return;
            }
            const provider = new firebase.auth.GoogleAuthProvider();
            window.auth.signInWithPopup(provider).then(function (result) {
                const gUser = result.user;
                const email = gUser.email;
                const displayName = gUser.displayName || email.split('@')[0];
                const photoURL = gUser.photoURL || '';

                // Check hardcoded admin
                const adminMatch = users.find(u => u.username === email);
                if (adminMatch) {
                    currentUser = { ...adminMatch };
                    sessionStorage.setItem('erp_user', JSON.stringify(currentUser));
                    completeLogin();
                    return;
                }

                let regUsers = [];
                try { regUsers = JSON.parse(localStorage.getItem('erp_registered_users')) || []; } catch (e) { }

                let existing = regUsers.find(u => u.email === email);

                if (existing) {
                    if (existing.status === 'approved') {
                        currentUser = { ...existing };
                        sessionStorage.setItem('erp_user', JSON.stringify(currentUser));
                        completeLogin();
                    } else if (existing.status === 'pending') {
                        showToast('Tài khoản của bạn đang chờ Admin phê duyệt. Vui lòng liên hệ quản trị viên.', 'warning');
                    } else {
                        showToast('Tài khoản đã bị từ chối. Vui lòng liên hệ quản trị viên.', 'error');
                    }
                } else {
                    const initials = displayName.split(' ').map(w => w[0]).join('').substring(0, 2).toUpperCase();
                    const newUser = {
                        id: 'GOOGLE_' + Date.now(),
                        username: email,
                        email: email,
                        fullName: displayName,
                        password: '',
                        role: 'Nhân viên',
                        department: 'Chưa phân bổ',
                        initials: initials,
                        avatar: photoURL,
                        status: 'pending',
                        permissions: ['trang-chu', 'ban-quyen'],
                        provider: 'google',
                        createdAt: new Date().toISOString(),
                        approvedBy: null
                    };
                    regUsers.push(newUser);
                    localStorage.setItem('erp_registered_users', JSON.stringify(regUsers));
                    if (window.CrudSync) { window.CrudSync.saveItem('erp_registered_users', newUser, 'username'); }
                    showToast('Đăng ký Google thành công! Tài khoản đang chờ Admin phê duyệt.', 'success');
                    addSystemNotification(
                        'Tài khoản Google mới: ' + displayName + ' (' + email + ')',
                        'user-register', 'blue',
                        { page: 'he-thong', module: 'Quản lý tài khoản' }
                    );
                }
            }).catch(function (error) {
                console.error('Google Auth Error:', error);
                showToast('Lỗi đăng nhập Google: ' + error.message, 'error');
            });
        }

        function completeLogin() {
            const loginScreen = document.getElementById('loginScreen');
            const appContainer = document.getElementById('appContainer');
            loginScreen.style.animation = 'fadeOut 0.3s ease forwards';
            setTimeout(() => {
                loginScreen.style.display = 'none';
                loginScreen.classList.add('hidden');
                loginScreen.style.animation = '';
                appContainer.style.display = 'flex';
                updateUserUI();
                updateSidebarVisibility();
                if (typeof navigateTo === 'function') { navigateTo('trang-chu'); }
            }, 300);
        }

        const googleLoginBtn = document.getElementById('googleLoginBtn');
        const googleRegisterBtn = document.getElementById('googleRegisterBtn');
        if (googleLoginBtn) { googleLoginBtn.onclick = handleGoogleAuth; }
        if (googleRegisterBtn) { googleRegisterBtn.onclick = handleGoogleAuth; }
    }

    function updateUserUI() {
        if (!currentUser) { return; }

        let hdName = currentUser.fullName;
        let hdRole = currentUser.role;
        let avInitials = currentUser.initials;
        let avatarData = null;

        if (typeof getProfileData === 'function') {
            const profile = getProfileData();
            hdName = profile.fullName;
            hdRole = profile.role;
            avatarData = profile.avatar;
        }

        const headerAvatar = document.getElementById('userAvatar');
        const headerDropdownAvatar = document.querySelector('.dropdown-avatar');

        if (avatarData) {
            if (headerAvatar) { headerAvatar.innerHTML = `<img src="${avatarData}" alt="avatar" style="width:100%;height:100%;object-fit:cover;border-radius:50%;"><div class="online-indicator"></div>`; }
            if (headerDropdownAvatar) { headerDropdownAvatar.innerHTML = `<img src="${avatarData}" alt="avatar" style="width:100%;height:100%;object-fit:cover;border-radius:50%;"><div class="online-indicator"></div>`; }
        } else {
            if (headerAvatar) { headerAvatar.innerHTML = `<span class="avatar-initials" id="avatarInitials">${avInitials}</span><div class="online-indicator"></div>`; }
            if (headerDropdownAvatar) { headerDropdownAvatar.innerHTML = `<span class="avatar-initials" id="dropdownInitials">${avInitials}</span><div class="online-indicator"></div>`; }
        }

        const els = {
            'headerUserName': hdName,
            'dropdownUserName': hdName,
            'headerUserRole': hdRole,
            'dropdownUserRole': hdRole
        };
        Object.entries(els).forEach(([id, val]) => {
            const el = document.getElementById(id);
            if (el) { el.textContent = val; }
        });
    }

    function handleLogout() {
        currentUser = null;
        sessionStorage.removeItem('erp_user');
        const loginScreen = document.getElementById('loginScreen');
        const appContainer = document.getElementById('appContainer');
        appContainer.style.display = 'none';
        loginScreen.classList.remove('hidden');
        loginScreen.style.display = 'flex';
        // Reset forms
        document.getElementById('loginForm').reset();
        document.getElementById('loginForm').style.display = 'flex';
        const regForm = document.getElementById('registerForm');
        if (regForm) { regForm.style.display = 'none'; }
        document.getElementById('loginError').textContent = '';
        document.getElementById('loginPassword').type = 'password';
        document.getElementById('togglePassword').querySelector('.material-icons-outlined').textContent = 'visibility_off';
        // Reset sidebar visibility
        document.querySelectorAll('.nav-item').forEach(item => { item.style.display = ''; });
        // Pre-fill remembered
        const remembered = localStorage.getItem('erp_remembered_user');
        if (remembered) {
            document.getElementById('loginUsername').value = remembered;
            document.getElementById('rememberMe').checked = true;
        }
    }

    // ==========================================
    // Sidebar Permission Visibility
    // ==========================================
    function updateSidebarVisibility() {
        if (!currentUser) { return; }
        // Admin always sees everything
        if (currentUser.role === 'Admin') { return; }
        const perms = currentUser.permissions || [];
        document.querySelectorAll('.nav-item').forEach(item => {
            const page = item.dataset.page;
            if (!page) { return; }
            if (['trang-chu', 'ban-quyen', 'tai-lieu'].includes(page)) { return; } // Always visible
            item.style.display = perms.includes(page) ? '' : 'none';
        });
    }
    window.erpApp.updateSidebarVisibility = updateSidebarVisibility;

    // ==========================================
    // Module: Quản lý tài khoản
    // ==========================================
    const MODULE_PAGES = [
        { page: 'hanh-chinh', icon: 'apartment', label: 'Hành chính', color: '#3B82F6' },


        { page: 'van-hanh', icon: 'miscellaneous_services', label: 'Quản lý dự án', color: '#8B5CF6' },
        { page: 'kinh-doanh', icon: 'storefront', label: 'Kinh doanh', color: '#F59E0B' },
        { page: 'marketing', icon: 'campaign', label: 'Marketing', color: '#EC4899' },
        { page: 'tai-chinh', icon: 'account_balance', label: 'Tài chính', color: '#10B981' },
        { page: 'mua-hang', icon: 'shopping_cart', label: 'Mua hàng', color: '#6366F1' },
        { page: 'san-xuat', icon: 'precision_manufacturing', label: 'Sản xuất', color: '#EF4444' },
        { page: 'kho-van', icon: 'inventory_2', label: 'Xưởng/Kho', color: '#14B8A6' },
        { page: 'dieu-hanh', icon: 'dashboard', label: 'Chiến lược', color: '#F97316' },
        { page: 'he-thong', icon: 'settings', label: 'Hệ thống', color: '#64748B' },
        { page: 'tro-ly-ai', icon: 'smart_toy', label: 'Trợ lý AI', color: '#A855F7' },
        { page: 'ban-quyen', icon: 'verified', label: 'Thông tin bản quyền', color: '#0EA5E9' }
    ];

    function renderQuanLyNguoiDung() {
        updateBreadcrumb('Quản lý người dùng', 'Hệ thống');
        let regUsers = [];
        try { regUsers = JSON.parse(localStorage.getItem('erp_registered_users')) || []; } catch (e) { }

        const pendingCount = regUsers.filter(u => u.status === 'pending').length;

        let rows = regUsers.map((u, idx) => {
            const statusClass = u.status || 'pending';
            const statusLabel = u.status === 'approved' ? 'Đã duyệt' : u.status === 'rejected' ? 'Từ chối' : 'Chờ duyệt';
            const providerIcon = u.provider === 'google' ? '<span style="color:#4285F4;font-weight:700">Google</span>' : 'Email';
            const dateStr = u.createdAt ? new Date(u.createdAt).toLocaleDateString('vi-VN') : '—';
            const actions = u.status === 'pending' ? `
                <button class="table-action-btn edit" onclick="window.erpApp.approveUserAccount(${idx})" title="Phê duyệt"><span class="material-icons-outlined" style="color:#16A34A">check_circle</span></button>
                <button class="table-action-btn delete" onclick="window.erpApp.rejectUserAccount(${idx})" title="Từ chối"><span class="material-icons-outlined" style="color:#DC2626">cancel</span></button>
            ` : `
                <button class="table-action-btn edit" onclick="window.erpApp.openUserPermissionModal(${idx})" title="Chỉnh sửa quyền"><span class="material-icons-outlined">tune</span></button>
                <button class="table-action-btn delete" onclick="window.erpApp.deleteUserAccount(${idx})" title="Xóa"><span class="material-icons-outlined">delete</span></button>
            `;
            return `<tr>
                <td><strong>${u.fullName}</strong></td>
                <td><code style="background:var(--bg-light);padding:2px 6px;border-radius:4px;color:var(--primary-color)">${u.username || '—'}</code></td>
                <td>${u.email}</td>
                <td>${providerIcon}</td>
                <td>${u.role || 'Nhân viên'}</td>
                <td>${u.department || '—'}</td>
                <td><span class="account-status-badge ${statusClass}">${statusLabel}</span></td>
                <td>${dateStr}</td>
                <td><div class="table-actions">${actions}</div></td>
            </tr>`;
        }).join('');

        if (!rows) { rows = '<tr><td colspan="9" style="text-align:center;padding:40px;color:var(--text-muted)"><span class="material-icons-outlined" style="font-size:40px;opacity:0.3">person_off</span><br>Chưa có tài khoản nào đăng ký</td></tr>'; }

        pageContent.innerHTML = `
            <button class="back-btn" onclick="window.erpApp.navigateTo('he-thong')"><span class="material-icons-outlined">arrow_back</span> Quay lại</button>
            <div style="display:flex;align-items:center;gap:12px;margin:16px 0">
                <div style="width:44px;height:44px;border-radius:10px;background:linear-gradient(135deg,#8B5CF6,#7C3AED);display:flex;align-items:center;justify-content:center;color:#fff;box-shadow:0 4px 12px rgba(139,92,246,0.3)"><span class="material-icons-outlined">manage_accounts</span></div>
                <div><div style="font-size:20px;font-weight:800;color:var(--text-primary)">Quản lý tài khoản</div>
                <div style="font-size:12px;color:var(--text-muted)">${regUsers.length} tài khoản · ${pendingCount} chờ duyệt</div></div>
            </div>
            <div style="overflow-x:auto;background:#fff;border-radius:12px;border:1.5px solid var(--border-color);box-shadow:0 2px 8px rgba(0,0,0,0.04)">
                <table class="data-table" style="width:100%;border-collapse:collapse">
                    <thead><tr>
                        <th>Họ tên</th><th>Tài khoản</th><th>Email</th><th>Nguồn</th><th>Vai trò</th><th>Phòng ban</th><th>Trạng thái</th><th>Ngày tạo</th><th>Hành động</th>
                    </tr></thead>
                    <tbody>${rows}</tbody>
                </table>
            </div>
        `;
    }

    window.erpApp.approveUserAccount = function (idx) {
        let regUsers = JSON.parse(localStorage.getItem('erp_registered_users')) || [];
        if (regUsers[idx]) {
            regUsers[idx].status = 'approved';
            regUsers[idx].approvedBy = currentUser?.fullName || 'Admin';
            regUsers[idx].permissions = ['trang-chu', 'ban-quyen', 'hanh-chinh'];
            localStorage.setItem('erp_registered_users', JSON.stringify(regUsers));
            if (window.CrudSync) { window.CrudSync.saveItem('erp_registered_users', regUsers[idx], 'username'); }

            // Gửi thông báo hệ thống
            window.erpApp.notifyCRUD('Tài khoản', 'update', {
                name: regUsers[idx].fullName,
                page: 'he-thong',
                module: 'Quản lý tài khoản'
            });

            renderQuanLyNguoiDung();
        }
    };

    window.erpApp.rejectUserAccount = function (idx) {
        let regUsers = JSON.parse(localStorage.getItem('erp_registered_users')) || [];
        if (regUsers[idx]) {
            regUsers[idx].status = 'rejected';
            localStorage.setItem('erp_registered_users', JSON.stringify(regUsers));
            if (window.CrudSync) { window.CrudSync.saveItem('erp_registered_users', regUsers[idx], 'username'); }

            // Gửi thông báo hệ thống
            window.erpApp.notifyCRUD('Tài khoản', 'delete', {
                name: regUsers[idx].fullName,
                page: 'he-thong',
                module: 'Quản lý tài khoản'
            });

            renderQuanLyNguoiDung();
        }
    };

    window.erpApp.deleteUserAccount = function (idx) {
        const regUsers = JSON.parse(localStorage.getItem('erp_registered_users')) || [];
        if (idx >= 0 && idx < regUsers.length) {
            const userToDelete = regUsers[idx];
            window.erpApp.showDeleteConfirmation(
                'Tài khoản',
                userToDelete.username,
                function () {
                    regUsers.splice(idx, 1);
                    localStorage.setItem('erp_registered_users', JSON.stringify(regUsers));
                    if (window.CrudSync) { window.CrudSync.deleteItem('erp_registered_users', userToDelete.username, 'username'); }
                    showToast('Đã xóa tài khoản thành công!');

                    // Gửi thông báo hệ thống
                    window.erpApp.notifyCRUD('Tài khoản', 'delete', {
                        name: userToDelete.fullName,
                        page: 'he-thong',
                        module: 'Quản lý tài khoản'
                    });

                    renderQuanLyNguoiDung();
                }
            );
        }
    };

    window.erpApp.openUserPermissionModal = function (idx) {
        let regUsers = JSON.parse(localStorage.getItem('erp_registered_users')) || [];
        const user = regUsers[idx];
        if (!user) { return; }
        const perms = user.permissions || [];

        const moduleRows = MODULE_PAGES.map(m => `
            <div class="perm-module-row">
                <div class="perm-module-info">
                    <div class="perm-module-icon" style="background:${m.color}"><span class="material-icons-outlined">${m.icon}</span></div>
                    <div class="perm-module-name">${m.label}</div>
                </div>
                <label class="perm-toggle">
                    <input type="checkbox" data-page="${m.page}" ${perms.includes(m.page) ? 'checked' : ''}>
                    <span class="perm-toggle-slider"></span>
                </label>
            </div>
        `).join('');

        const overlay = document.createElement('div');
        overlay.className = 'modal-overlay';
        overlay.id = 'permModal';
        overlay.style = 'background:rgba(15,23,42,0.6); backdrop-filter:blur(4px); position:fixed; top:0; left:0; width:100%; height:100%; z-index:9999; display:flex; align-items:center; justify-content:center;';
        overlay.innerHTML = `
            <div class="modal-content" style="width:480px; max-width:95%; max-height:90vh; background:#fff; border-radius:16px; overflow:hidden; box-shadow:0 25px 50px -12px rgba(0,0,0,0.25); animation:modalPop 0.3s ease-out; display:flex; flex-direction:column;">
                <div class="modal-header" style="background:#f8fafc; border-bottom:1px solid #f1f5f9; padding:20px 24px; display:flex; justify-content:space-between; align-items:center; flex-shrink:0;">
                    <h2 style="margin:0; font-size:17px; font-weight:800; color:#1e293b; display:flex; align-items:center; gap:10px;">
                        <div style="width:36px; height:36px; background:#e0e7ff; border-radius:10px; display:flex; align-items:center; justify-content:center; color:#4f46e5;">
                            <span class="material-icons-outlined" style="font-size:20px;">admin_panel_settings</span>
                        </div>
                        Phân quyền: ${user.fullName}
                    </h2>
                    <button onclick="document.getElementById('permModal').remove()" style="width:32px; height:32px; border-radius:50%; border:none; background:#fff; cursor:pointer; color:#94a3b8; display:flex; align-items:center; justify-content:center; box-shadow:0 2px 8px rgba(0,0,0,0.05); transition:0.2s;" onmouseover="this.style.background='#f1f5f9'" onmouseout="this.style.background='#fff'">
                        <span class="material-icons-outlined" style="font-size:18px;">close</span>
                    </button>
                </div>
                <div class="modal-body" style="padding:24px; overflow-y:auto; flex:1; background:#fff;">
                    <div style="font-size:13px; color:#64748b; margin-bottom:16px; padding:12px; background:#f8fafc; border-radius:10px; border:1px solid #f1f5f9; line-height:1.5;">
                        Bật/tắt quyền truy cập từng module cho người dùng này. Các module không được chọn sẽ tự động bị ẩn.
                    </div>
                    <div style="display:flex; flex-direction:column; gap:10px;">
                        ${moduleRows}
                    </div>
                </div>
                <div class="modal-footer" style="padding:16px 24px; background:#f8fafc; border-top:1px solid #f1f5f9; display:flex; justify-content:flex-end; gap:10px; flex-shrink:0;">
                    <button class="btn-cancel" onclick="document.getElementById('permModal').remove()" style="padding:10px 20px; border-radius:10px; border:1px solid #e2e8f0; background:#fff; font-weight:700; color:#64748b; cursor:pointer; font-size:13px; transition:0.2s;" onmouseover="this.style.background='#f8fafc'">Hủy</button>
                    <button class="btn-save" id="savePermBtn" style="padding:10px 24px; border-radius:10px; border:none; background:#4f46e5; color:#fff; font-weight:700; cursor:pointer; font-size:13px; box-shadow:0 4px 12px rgba(79, 70, 229, 0.3); transition:0.2s;" onmouseover="this.style.transform='translateY(-1px)'">Lưu phân quyền</button>
                </div>
            </div>
        `;
        document.body.appendChild(overlay);

        document.getElementById('savePermBtn').onclick = function () {
            const checks = overlay.querySelectorAll('input[type=checkbox]');
            const newPerms = ['trang-chu'];
            checks.forEach(c => { if (c.checked) { newPerms.push(c.dataset.page); } });
            regUsers[idx].permissions = [...new Set(newPerms)];
            localStorage.setItem('erp_registered_users', JSON.stringify(regUsers));
            if (window.CrudSync) { window.CrudSync.saveItem('erp_registered_users', regUsers[idx], 'username'); }
            overlay.remove();

            // Gửi thông báo hệ thống
            window.erpApp.notifyCRUD('Phân quyền', 'update', {
                name: regUsers[idx].fullName,
                page: 'he-thong',
                module: 'Quản lý tài khoản'
            });

            renderQuanLyNguoiDung();
        };
    };


