    // RBAC Helpers
    window.erpApp.userHasAccess = function (moduleName, permission = 'view') {
        if (!currentUser) { return false; }

        // Admin luôn có quyền truy cập toàn bộ
        if (currentUser.role === 'Admin') { return true; }

        // Kiểm tra quyền cụ thể gán cho tài khoản (từ lúc đăng ký hoặc admin chỉnh sửa)
        // Ánh xạ title sang page key để kiểm tra trong mảng permissions
        const titleToPageMap = {
            'Hành chính': 'hanh-chinh',
            'Quản lý dự án': 'van-hanh',
            'Kinh doanh': 'kinh-doanh',
            'Marketing': 'marketing',
            'Tài chính - Kế toán': 'tai-chinh',
            'Mua hàng': 'mua-hang',
            'Sản xuất': 'san-xuat',
            'Xưởng sản xuất, kho': 'kho-van',
            'Chiến lược kinh doanh': 'dieu-hanh',
            'Hệ thống': 'he-thong',
            'Trợ lý AI': 'tro-ly-ai',
            'Đào tạo': 'dao-tao',
            'Thông tin bản quyền': 'ban-quyen'
        };
        const pageKey = titleToPageMap[moduleName];
        if (pageKey && currentUser.permissions && currentUser.permissions.includes(pageKey)) {
            return true;
        }

        // Kiểm tra quyền theo Vai trò (Role-based) trong systemPermissions
        const perms = systemPermissions[moduleName];
        if (!perms) { return false; }

        const userRole = currentUser.role || currentUser.chucVu;
        if (!userRole) { return false; }

        const rolePerms = perms[userRole];
        if (!rolePerms) { return false; }

        return !!rolePerms[permission] || !!rolePerms['all'];
    };

