    const defaultVehicles = [];

    const loadVMData = (key, defaults) => {
        try {
            const saved = localStorage.getItem('erp_' + key);
            if (saved) {
                let data = JSON.parse(saved);
                // Migration: Ensure context for vehicles
                if (key === 'vmVehicles' && Array.isArray(data)) {
                    let changed = false;
                    data.forEach(v => {
                        // Broaden the check for equipment context
                        const isEquip = v.context === 'equipment' ||
                            v.type === 'Thiết bị thi công' ||
                            (v.id && String(v.id).startsWith('TB-')) ||
                            (v.internalCode && String(v.internalCode).startsWith('M-'));

                        if (isEquip && v.context !== 'equipment') {
                            v.context = 'equipment';
                            changed = true;
                        } else if (!isEquip && !v.context) {
                            v.context = 'vehicle';
                            changed = true;
                        }
                    });
                    if (changed) { localStorage.setItem('erp_vmVehicles', JSON.stringify(data)); }
                }
                return data;
            }
        } catch (e) { console.error(`Error loading VM data [${key}]`, e); }
        return (defaults && defaults.length > 0) ? defaults : [];
    };

