    window.erpApp.exportAllData = () => {
        const fullData = {};
        for (let i = 0; i < localStorage.length; i++) {
            const key = localStorage.key(i);
            if (key.startsWith('erp_') || key === 'employees' || key === 'productList') {
                try {
                    fullData[key] = JSON.parse(localStorage.getItem(key));
                } catch (e) {
                    fullData[key] = localStorage.getItem(key);
                }
            }
        }

        const blob = new Blob([JSON.stringify(fullData, null, 2)], { type: 'application/json' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        const timestamp = new Date().toISOString().slice(0, 19).replace(/[:T]/g, '_');
        a.download = `vietbachcorp_erp_full_backup_${timestamp}.json`;
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        URL.revokeObjectURL(url);

        if (typeof showToast === 'function') { showToast('Đã xuất file sao lưu hệ thống thành công!', 'success'); }
        return fullData;
    };

    window.erpApp.handleRestoreFile = (input) => {
        const file = input.files[0];
        if (!file) { return; }

        const reader = new FileReader();
        reader.onload = async (e) => {
            try {
                const data = JSON.parse(e.target.result);
                if (typeof data !== 'object') { throw new Error('Định dạng file không hợp lệ'); }

                window.erpApp.showConfirm(
                    'Xác nhận khôi phục',
                    '<span style="color: #ef4444; font-weight: 700;">CẢNH BÁO:</span> Việc khôi phục sẽ ghi đè lên dữ liệu hiện tại. Bạn có chắc chắn muốn tiếp tục?',
                    async function () {
                        // Restore each key
                        Object.keys(data).forEach(key => {
                            if (typeof data[key] === 'object') {
                                localStorage.setItem(key, JSON.stringify(data[key]));
                            } else {
                                localStorage.setItem(key, data[key]);
                            }
                        });

                        // Sync with Firestore if possible
                        if (window.SyncManager && window.SyncManager.forceUploadAllLocalData) {
                            window.erpApp.showConfirm(
                                'Đồng bộ Cloud',
                                'Dữ liệu đã khôi phục vào máy. Bạn có muốn đồng bộ ngay lên Cloud không?',
                                async function () {
                                    await window.SyncManager.forceUploadAllLocalData();
                                    finishRestore();
                                },
                                function () { // On Cancel
                                    finishRestore();
                                }
                            );
                        } else {
                            finishRestore();
                        }

                        function finishRestore() {
                            if (typeof showToast === 'function') { showToast('Khôi phục dữ liệu thành công! Hệ thống sẽ tải lại.', 'success'); }
                            setTimeout(() => location.reload(), 2000);
                        }
                    },
                    function () {
                        input.value = '';
                    }
                );

            } catch (err) {
                console.error('Restore Error:', err);
                if (typeof showToast === 'function') { showToast('Lỗi khi đọc file: ' + err.message, 'error'); }
            }
        };
        reader.readAsText(file);
    };

    window.erpApp.terminateSession = (id) => {
        const session = systemSessions.find(s => s.id === id);
        if (!session) { return; }

        const overlay = document.createElement('div');
        overlay.className = 'modal-overlay';
        overlay.id = 'terminateConfirmModal';
        overlay.innerHTML = `
            <div class="modal-content" style="max-width:420px; text-align:center; padding:30px;">
                <div style="width:64px; height:64px; background:#fef2f2; color:#ef4444; border-radius:50%; display:flex; align-items:center; justify-content:center; margin:0 auto 20px;">
                    <span class="material-icons-outlined" style="font-size:36px;">logout</span>
                </div>
                <h3 style="margin-bottom:12px; font-size:18px; color:#1e293b;">Đăng xuất thiết bị?</h3>
                <p style="color:#64748b; font-size:14px; margin-bottom:24px;">Bạn có chắc chắn muốn đăng xuất tài khoản <strong>${session.account}</strong> khỏi thiết bị <strong>${session.device}</strong>?</p>
                <div style="display:flex; gap:12px; justify-content:center;">
                    <button class="btn-cancel" onclick="this.closest('.modal-overlay').remove()" style="padding:10px 24px; border:1px solid #e2e8f0; background:#fff; border-radius:8px; cursor:pointer; font-weight:600; color:#64748b;">Hủy bỏ</button>
                    <button class="btn-save" onclick="window.erpApp.doTerminateSession('${id}')" style="padding:10px 24px; border:none; background:#ef4444; color:#fff; border-radius:8px; cursor:pointer; font-weight:600;">Xác nhận đăng xuất</button>
                </div>
            </div>
        `;
        document.body.appendChild(overlay);
    };

    window.erpApp.doTerminateSession = (id) => {
        systemSessions = systemSessions.map(s => s.id === id ? { ...s, status: 'logged_out' } : s);
        localStorage.setItem('erp_sessions', JSON.stringify(systemSessions));
        const modal = document.getElementById('terminateConfirmModal');
        if (modal) { modal.remove(); }
        showToast('Đã đăng xuất thiết bị thành công!');
        renderThietBiDangNhap();
    };

