    window.erpApp.generateAIRecommendations = () => {
        const container = document.getElementById('aiRecommendationsList');
        if (!container) { return; }

        // Simulate AI analysis delay
        container.innerHTML = `
            <div style="grid-column: span 3; text-align:center; padding:40px;">
                <div class="material-icons-outlined animate-spin" style="font-size:40px; color:#4f46e5; margin-bottom:12px;">sync</div>
                <div style="font-size:14px; color:#64748b; font-weight:600;">AI đang xử lý các chiều dữ liệu...</div>
            </div>
        `;

        setTimeout(() => {
            const recommendations = [];

            // 1. Inventory Insights
            const lowStockProducts = productList.filter(p => (p.stock || 0) < 20);
            if (lowStockProducts.length > 0) {
                recommendations.push({
                    id: 'REC001',
                    category: 'Kho vận',
                    title: 'Tối ưu hóa tồn kho hàng hóa',
                    desc: `Có ${lowStockProducts.length} mặt hàng đang dưới ngưỡng an toàn (<20). Hệ thống đề xuất nhập thêm để tránh gián đoạn kinh doanh.`,
                    score: 98,
                    priority: 'High',
                    icon: 'inventory_2',
                    color: '#ef4444',
                    actionLabel: 'Nhập hàng ngay',
                    actionPage: 'kho-van'
                });
            }

            // 2. HR Insights
            const expiringContracts = employees.filter(e => {
                // Giả lập check ngày hết hạn hợp đồng
                return Math.random() > 0.7;
            }).slice(0, 2);

            recommendations.push({
                id: 'REC002',
                category: 'Nhân sự',
                title: 'Kế hoạch gia hạn hợp đồng',
                desc: `Dựa trên phân tích hiệu suất và ngày kết thúc hợp đồng, AI đề xuất gia hạn cho ${expiringContracts.length + 1} nhân sự xuất sắc.`,
                score: 92,
                priority: 'Medium',
                icon: 'badge',
                color: '#3b82f6',
                actionLabel: 'Xem danh sách',
                actionPage: 'hanh-chinh'
            });

            // 3. Operational Insights
            recommendations.push({
                id: 'REC003',
                category: 'Kế hoạch',
                title: 'Điều phối nguồn lực sản xuất',
                desc: 'Đơn hàng FG-001 đang tăng đột biến 15%. AI đề xuất tăng cường nhân sự từ tổ May sang tổ Kiểm tra.',
                score: 87,
                priority: 'Medium',
                icon: 'precision_manufacturing',
                color: '#a855f7',
                actionLabel: 'Điều phối ngay',
                actionPage: 'san-xuat'
            });

            // 4. CRM Insights
            recommendations.push({
                id: 'REC004',
                category: 'Kinh doanh',
                title: 'Chăm sóc khách hàng tiềm năng',
                desc: 'Có 12 khách hàng VIP chưa phát sinh giao dịch trong 3 tháng qua. AI đề xuất gửi chương trình khuyến mãi riêng.',
                score: 95,
                priority: 'High',
                icon: 'groups',
                color: '#f59e0b',
                actionLabel: 'Gửi Email',
                actionPage: 'marketing'
            });

            container.innerHTML = recommendations.map(rec => `
                <div class="ai-card" data-category="${rec.category}" style="background:#fff; border:1px solid #e2e8f0; border-radius:16px; padding:20px; transition:all 0.3s; cursor:pointer; position:relative;" onclick="window.erpApp.viewRecommendationDetail('${rec.id}')">
                    <div style="display:flex; justify-content:space-between; align-items:flex-start; margin-bottom:16px;">
                        <div style="width:40px; height:40px; background:${rec.color}15; color:${rec.color}; border-radius:10px; display:flex; align-items:center; justify-content:center;">
                            <span class="material-icons-outlined">${rec.icon}</span>
                        </div>
                        <div style="text-align:right;">
                            <div style="font-size:10px; color:#94a3b8; font-weight:700; text-transform:uppercase;">Độ tin cậy</div>
                            <div style="font-size:14px; font-weight:800; color:#4f46e5;">${rec.score}%</div>
                        </div>
                    </div>
                    <div style="display:inline-block; padding:3px 8px; background:#f1f5f9; border-radius:5px; font-size:10px; font-weight:700; color:#64748b; margin-bottom:10px; text-transform:uppercase;">
                        ${rec.category}
                    </div>
                    <h4 style="margin:0 0 8px; font-size:15px; font-weight:800; color:#1e293b; line-height:1.4;">${rec.title}</h4>
                    <p style="margin:0 0 16px; font-size:12px; color:#64748b; line-height:1.6; display: -webkit-box; -webkit-line-clamp: 3; -webkit-box-orient: vertical; overflow: hidden;">
                        ${rec.desc}
                    </p>
                    <div style="display:flex; align-items:center; justify-content:space-between;">
                        <span style="font-size:12px; font-weight:700; color:${rec.priority === 'High' ? '#ef4444' : '#f59e0b'}; display:flex; align-items:center; gap:4px;">
                            <span class="material-icons-outlined" style="font-size:14px;">priority_high</span> ${rec.priority}
                        </span>
                        <span class="material-icons-outlined" style="color:#cbd5e1;">arrow_forward</span>
                    </div>
                </div>
            `).join('');

            // Save for detail view
            window.lastAIRecommendations = recommendations;
        }, 800);
    };

    window.erpApp.filterAIRecommendations = function (category, btn) {
        // Toggle active class on buttons
        const tabs = document.getElementById('aiRecommendTabs');
        if (tabs) {
            tabs.querySelectorAll('.btn-subtab').forEach(b => b.classList.remove('active'));
            btn.classList.add('active');
        }

        // Simulating the actual data filter
        const container = document.getElementById('aiRecommendationsList');
        if (!container) { return; }

        // Visual feedback (shimmer/fade effect)
        container.style.opacity = '0.4';
        container.style.transition = 'opacity 0.2s';

        setTimeout(() => {
            container.style.opacity = '1';
            const allItems = container.querySelectorAll('.ai-card');
            allItems.forEach(item => {
                const itemCat = item.getAttribute('data-category')?.toLowerCase().trim() || '';
                const filterCat = category.toLowerCase().trim();

                if (filterCat === 'all' || itemCat === filterCat || itemCat.includes(filterCat)) {
                    item.style.display = 'block';
                    item.style.animation = 'fadeIn 0.3s ease-out';
                } else {
                    item.style.display = 'none';
                }
            });
        }, 200);
    };

    window.erpApp.viewRecommendationDetail = (id) => {
        const rec = window.lastAIRecommendations.find(r => r.id === id);
        if (!rec) { return; }

        const overlay = document.createElement('div');
        overlay.className = 'modal-overlay';
        overlay.innerHTML = `
            <div class="modal-content" style="max-width:550px;">
                <div class="modal-header" style="background:linear-gradient(135deg, ${rec.color}05 0%, #fff 100%);">
                    <h2><span class="material-icons-outlined" style="color:${rec.color}">${rec.icon}</span> Chi tiết Đề xuất AI</h2>
                    <button class="modal-close" onclick="this.closest('.modal-overlay').remove()"><span class="material-icons-outlined">close</span></button>
                </div>
                <div class="modal-body" style="padding:24px;">
                    <div style="margin-bottom:24px;">
                        <div style="display:inline-block; font-size:12px; font-weight:800; color:#fff; background:${rec.color}; padding:4px 12px; border-radius:20px; margin-bottom:12px;">
                            ${rec.category.toUpperCase()}
                        </div>
                        <h3 style="font-size:20px; font-weight:800; color:#1e293b; margin-bottom:8px;">${rec.title}</h3>
                        <p style="color:#64748b; line-height:1.6; font-size:14px;">${rec.desc}</p>
                    </div>

                    <div style="background:#f8fafc; border:1px solid #e2e8f0; border-radius:12px; padding:16px; margin-bottom:24px;">
                        <h4 style="font-size:13px; font-weight:700; color:#1e293b; margin-bottom:12px; display:flex; align-items:center; gap:8px;">
                            <span class="material-icons-outlined" style="font-size:18px; color:#4f46e5;">analytics</span> Tại sao AI gợi ý điều này?
                        </h4>
                        <div style="display:grid; grid-template-columns:1fr 1fr; gap:12px;">
                            <div style="background:#fff; padding:10px; border-radius:8px; border:1px solid #f1f5f9;">
                                <div style="font-size:11px; color:#94a3b8; font-weight:600; margin-bottom:4px;">Dữ liệu tham chiếu</div>
                                <div style="font-size:13px; font-weight:700; color:#334155;">Lịch sử giao dịch 6 tháng</div>
                            </div>
                            <div style="background:#fff; padding:10px; border-radius:8px; border:1px solid #f1f5f9;">
                                <div style="font-size:11px; color:#94a3b8; font-weight:600; margin-bottom:4px;">Tác động dự kiến</div>
                                <div style="font-size:13px; font-weight:700; color:#10b981;">Tăng 12% hiệu quả</div>
                            </div>
                        </div>
                    </div>

                    <div style="display:flex; align-items:center; gap:10px; padding:12px; background:#f0f9ff; border-radius:10px; border:1px solid #bae6fd;">
                        <span class="material-icons-outlined" style="color:#0369a1;">lightbulb</span>
                        <div style="font-size:12px; color:#0c4a6e;">
                            Hệ thống tự động đồng bộ đề xuất này với bộ phận <b>${rec.category}</b> để cùng phối hợp xử lý.
                        </div>
                    </div>
                </div>
                <div class="modal-footer">
                    <button class="btn-cancel" onclick="this.closest('.modal-overlay').remove()">Bỏ qua</button>
                    <button class="btn-save" style="background:${rec.color};" onclick="this.closest('.modal-overlay').remove(); window.erpApp.navigateTo('${rec.actionPage}')">
                        ${rec.actionLabel}
                    </button>
                </div>
            </div>
        `;
        document.body.appendChild(overlay);
    };


