    window.erpApp.sendAIMessage = function (text) {
        const list = document.getElementById('aiMessageList');
        const input = document.getElementById('aiChatInput');
        if (!list) { return; }
        if (input) { input.value = ''; }

        // User message
        const userMsg = document.createElement('div');
        userMsg.className = 'ai-message user';
        userMsg.innerHTML = `
            <div style="font-size: 11px; opacity: 0.8; margin-bottom: 4px; text-align: right;">${new Date().toLocaleTimeString('vi-VN', { hour: '2-digit', minute: '2-digit' })}</div>
            ${text}
        `;
        list.appendChild(userMsg);
        list.scrollTop = list.scrollHeight;

        // Typing indicator
        const typing = document.getElementById('aiTypingIndicator');
        if (typing) {
            typing.style.display = 'block';
            list.appendChild(typing);
        }
        list.scrollTop = list.scrollHeight;

        const parseAIResponse = (text) => {
            if (typeof text !== 'string') {
                console.warn('parseAIResponse: input is not a string', text);
                text = String(text || '');
            }
            let res = text;
            res = res.replace(/\*\*(.*?)\*\*/g, '<b>$1</b>');
            if (res.includes('|')) {
                const lines = res.split('\n');
                let tableHtml = '<table>';
                let inTable = false;
                const filteredLines = [];
                lines.forEach(line => {
                    if (line.trim().startsWith('|')) {
                        if (!inTable) { inTable = true; }
                        const cells = line.split('|').filter(c => c.trim() !== '').map(c => c.trim());
                        if (cells.length > 0) {
                            tableHtml += `<tr>${cells.map(c => `<td>${c}</td>`).join('')}</tr>`;
                        }
                    } else {
                        if (inTable) {
                            tableHtml += '</table>';
                            filteredLines.push(tableHtml);
                            tableHtml = '<table>';
                            inTable = false;
                        }
                        filteredLines.push(line);
                    }
                });
                if (inTable) {
                    tableHtml += '</table>';
                    filteredLines.push(tableHtml);
                }
                res = filteredLines.join('<br>');
            } else {
                res = res.replace(/\n/g, '<br>');
            }
            return res;
        };

        (async () => {
            let response = '';
            try {
                if (typeof window.getGeminiResponse === 'function') {
                    const systemContext = window.erpApp.getDeepSystemContext();
                    const persona = window.erpApp._currentPersona || 'default';
                    response = await window.getGeminiResponse(text, systemContext, persona);
                } else {
                    throw new Error('Gemini function not ready');
                }

                if (typing) { typing.style.display = 'none'; }

                const botMsg = document.createElement('div');
                botMsg.className = 'ai-message bot';
                botMsg.innerHTML = `
                    <div style="display:flex; align-items:center; gap:8px; margin-bottom:8px;">
                        <div class="ai-message-avatar" style="background: linear-gradient(135deg, #3b82f6, #2563eb); color: white;">
                            <span class="material-icons-outlined" style="font-size:16px;">psychology</span>
                        </div>
                        <span style="font-weight:700; font-size:12px;">Vietbach AI</span>
                        <span style="font-size: 10px; color: #94a3b8; margin-left: auto;">${new Date().toLocaleTimeString('vi-VN', { hour: '2-digit', minute: '2-digit' })}</span>
                    </div>
                    <div class="bot-content">${parseAIResponse(response)}</div>
                `;
                list.appendChild(botMsg);
                list.scrollTop = list.scrollHeight;
            } catch (err) {
                console.warn('Gemini Error:', err);
                if (typing) { typing.style.display = 'none'; }
                const errBotMsg = document.createElement('div');
                errBotMsg.className = 'ai-message bot';
                errBotMsg.style.borderLeft = '4px solid #ef4444';
                errBotMsg.innerHTML = `⚠️ <b>Lỗi kết nối:</b> ${err.message}. Vui lòng kiểm tra API Key hoặc kết nối mạng.`;
                list.appendChild(errBotMsg);
                list.scrollTop = list.scrollHeight;
            }
        })();
    };

    // Helper to gather comprehensive system data for AI - SAFE VERSION
    window.erpApp.getDeepSystemContext = function () {
        try {
            const getCount = (arr) => (Array.isArray(arr) ? arr.length : 0);
            const safeFilter = (arr, fn) => (Array.isArray(arr) ? arr.filter(fn) : []);
            const safeReduce = (arr, fn, init) => (Array.isArray(arr) ? arr.reduce(fn, init) : init);
            const formatValue = (val) => new Intl.NumberFormat('vi-VN').format(val || 0);

            // 1. HR & ADMIN
            const totalEmp = getCount(typeof employees !== 'undefined' ? employees : []);
            const deptStats = {};
            if (typeof employees !== 'undefined' && Array.isArray(employees)) {
                employees.forEach(e => { if (e.department) { deptStats[e.department] = (deptStats[e.department] || 0) + 1; } });
            }

            const cvAll = typeof congVanList !== 'undefined' ? congVanList : [];
            const cvPending = safeFilter(cvAll, cv => cv.status === 'pending' || cv.status === 'waiting');
            const pendingCVNames = cvPending.slice(0, 5).map(cv => cv.title).join(', ');

            const cvIncomingCount = safeFilter(cvAll, cv => cv.type === 'den').length;
            const cvOutgoingCount = safeFilter(cvAll, cv => cv.type === 'di').length;
            const cvInternalCount = safeFilter(cvAll, cv => cv.type === 'noi-bo').length;

            const hsAll = typeof hoSoDocuments !== 'undefined' ? hoSoDocuments : [];
            const hsCount = hsAll.length;
            const hsRecent = hsAll.slice(-5).map(d => `${d.id}: ${d.title || d.name}`).join(', ');

            // 2. SALES & CUSTOMERS
            const salesData = (typeof window.salesOrders !== 'undefined') ? window.salesOrders : [];
            const revenue = safeReduce(salesData, (sum, o) => sum + (o.totalAmount || 0), 0);
            const topCustomers = safeFilter(typeof window.customers !== 'undefined' ? window.customers : [], c => true).slice(0, 5).map(c => c.name).join(', ');
            const recentOrders = salesData.slice(-5).map(o => `${o.id} (${o.customerName || 'N/A'}): ${formatValue(o.totalAmount)} VND`).join('\n- ');

            // 3. FINANCE & DEBT
            const debtData = typeof window.erp_debt_partners !== 'undefined' ? window.erp_debt_partners : [];
            const totalPayable = safeReduce(debtData, (sum, d) => sum + (d.amount || 0), 0);
            const topDebtors = debtData.sort((a, b) => (b.amount || 0) - (a.amount || 0)).slice(0, 5).map(d => `${d.partnerName}: ${formatValue(d.amount)}`).join(', ');

            const transData = typeof window.erp_tc_transactions !== 'undefined' ? window.erp_tc_transactions : [];
            const recentTrans = transData.slice(-3).map(t => `${t.type === 'in' ? 'Thu' : 'Chi'}: ${formatValue(t.amount)} (${t.category})`).join(', ');

            // 4. PROJECTS & TASKS - DEEP SCAN
            const projectData = typeof window.pmProjects !== 'undefined' ? window.pmProjects : (typeof pmProjects !== 'undefined' ? pmProjects : []);
            const taskData = typeof window.pmTasks !== 'undefined' ? window.pmTasks : (typeof pmTasks !== 'undefined' ? pmTasks : []);
            const contractData = typeof window.pmContracts !== 'undefined' ? window.pmContracts : (typeof pmContracts !== 'undefined' ? pmContracts : []);

            const detailedProjects = projectData.slice(0, 25).map(p => {
                const pTasks = safeFilter(taskData, t => t.projectId === p.id || t.project === p.name);
                const pContracts = safeFilter(contractData, c => c.projectId === p.id || (c.projectName === p.name));

                // Finance deep aggregation
                const pFinance = safeFilter(typeof window.pmFinanceRecords !== 'undefined' ? window.pmFinanceRecords : [], f => f.projectId === p.id);
                const pExp = safeFilter(typeof window.pmContractedExpenses !== 'undefined' ? window.pmContractedExpenses : [], f => f.projectId === p.id);

                const rev = safeReduce(safeFilter(pFinance, f => f.type === 'thu' || f.type === 'revenue'), (sum, f) => sum + (f.amount || 0), 0);
                const exp = safeReduce(safeFilter(pFinance, f => f.type === 'chi' || f.type === 'expense'), (sum, f) => sum + (f.amount || 0), 0)
                    + safeReduce(pExp, (sum, f) => sum + (f.amount || 0), 0);
                const cVal = safeReduce(pContracts, (sum, c) => sum + (c.value || 0), 0);

                return `--- DỰ ÁN: ${p.name} ---
  * Mã dự án: ${p.id} | Trạng thái: ${p.status} | Tiến độ: ${p.progress || 0}%
  * TÀI CHÍNH DỰ ÁN:
    + Giá trị HĐ ký kết: ${formatValue(cVal)} VND
    + Đã thu từ khách hàng: ${formatValue(rev)} VND
    + CÔNG NỢ PHẢI THU (Dự án này): ${formatValue(cVal - rev)} VND
    + Tổng chi phí đã chi: ${formatValue(exp)} VND
    + Ngân sách dự kiến: ${formatValue(p.budget)} VND
  * NHÂN SỰ: Quản lý: ${p.manager || 'N/A'}
  * THỜI GIAN: ${p.startDate || '?'} -> ${p.endDate || '?'}
  * HỢP ĐỒNG LIÊN QUAN: ${pContracts.length} (${pContracts.slice(0, 3).map(c => c.title || c.name).join(', ')})
  * CÔNG VIỆC: ${pTasks.length} (${pTasks.slice(0, 5).map(t => t.name).join(', ')})`;
            }).join('\n\n');

            const allProjectNames = projectData.map(p => p.name).join(', ');
            const urgentTasks = safeFilter(taskData, t => t.priority === 'High' && t.status !== 'Completed').slice(0, 10).map(t => `${t.name} (${t.project || 'N/A'})`).join(', ');

            // 5. BIDDING & ESTIMATION
            const biddingData = typeof window.biddingPackages !== 'undefined' ? window.biddingPackages : [];
            const bidsCount = biddingData.length;
            const wonBids = safeFilter(biddingData, b => b.status === 'won').length;
            const biddingSummary = biddingData.slice(0, 8).map(b => `${b.name} (${b.status}): ${formatValue(b.value)}`).join(', ');

            // 6. PRODUCTION (MO/BOM)
            const moList = (typeof window.manufacturingOrders !== 'undefined') ? window.manufacturingOrders : [];
            const runningMO = safeFilter(moList, mo => mo.status === 'running' || mo.status === 'in_progress');
            const moNames = runningMO.slice(0, 5).map(mo => `${mo.id} (${mo.productName || 'N/A'})`).join(', ');
            const totalBOMs = getCount(typeof window.boms !== 'undefined' ? window.boms : (typeof boms !== 'undefined' ? boms : []));

            // 7. INVENTORY & WAREHOUSE
            const stockData = typeof window.danhSachHangHoaData !== 'undefined' ? window.danhSachHangHoaData : (typeof danhSachHangHoaData !== 'undefined' ? danhSachHangHoaData : []);
            const totalSKUs = getCount(stockData);
            const lowStockItems = safeFilter(stockData, i => i.stock < (i.minStock || 0));
            const lowStockDetails = lowStockItems.slice(0, 8).map(i => `${i.name} (Tồn: ${i.stock} ${i.unit || ''})`).join(', ');
            const inventoryValue = safeReduce(stockData, (sum, i) => sum + (i.stock * (i.price || 0)), 0);

            // 8. FLEET & LOGISTICS
            const vehicleList = typeof window.vmVehicles !== 'undefined' ? window.vmVehicles : (typeof vmVehicles !== 'undefined' ? vmVehicles : []);
            const maintenanceDue = safeFilter(typeof window.vmMaintenance !== 'undefined' ? window.vmMaintenance : (typeof vmMaintenance !== 'undefined' ? vmMaintenance : []), m => m.status === 'pending').slice(0, 5).map(m => m.vehicleId).join(', ');

            // 9. ALL ENTITY NAMES (For Fuzzy Search)
            const allCustomerNames = (typeof window.customers !== 'undefined' ? window.customers : []).map(c => c.name).join(', ');
            const allSupplierNames = (typeof window.suppliers !== 'undefined' ? window.suppliers : []).map(s => s.name).join(', ');
            const allMONames = moList.map(mo => mo.id).join(', ');

            return `
[DỮ LIỆU HỆ THỐNG VIETBACH ERP - CẬP NHẬT: ${new Date().toLocaleString('vi-VN')}]

1. NHÂN SỰ & HÀNH CHÍNH:
- Tổng số nhân viên: ${totalEmp}
- Cơ cấu phòng ban: ${JSON.stringify(deptStats)}
- Công văn: Đến (${cvIncomingCount}), Đi (${cvOutgoingCount}), Nội bộ (${cvInternalCount})
- Chờ duyệt: ${pendingCVNames || 'Không có'}
- Lưu trữ hồ sơ: Tổng (${hsCount}), Gần đây: ${hsRecent || 'Trống'}

2. KINH DOANH & KHÁCH HÀNG:
- Tổng doanh thu: ${formatValue(revenue)} VND
- Danh sách KH: ${allCustomerNames || 'Trống'}
- 5 đơn gần nhất: ${recentOrders || 'Không có'}

3. TÀI CHÍNH & CÔNG NỢ:
- Tổng nợ phải trả: ${formatValue(totalPayable)} VND
- Giao dịch gần nhất: ${recentTrans || 'Không có'}

4. DỰ ÁN & CÔNG VIỆC:
- Dữ liệu chi tiết:
${detailedProjects || 'Không có dữ liệu chi tiết'}
- TẤT CẢ TÊN DỰ ÁN: ${allProjectNames || 'Trống'}
- Công việc khẩn cấp: ${urgentTasks || 'Không có'}

5. ĐẤU THẦU & DỰ TOÁN:
- Tổng số gói thầu: ${bidsCount}
- Gói thầu đã trúng (Won): ${wonBids}
- Tóm tắt thầu: ${biddingSummary || 'Không có'}

6. SẢN XUẤT & KHO:
- Lệnh SX (MO) đang chạy: ${runningMO.length} (${moNames}...)
- TẤT CẢ MÃ LỆNH SX: ${allMONames || 'Trống'}
- Giá trị tồn kho: ${formatValue(inventoryValue)} VND
- CẢNH BÁO HẾT HÀNG: ${lowStockDetails || 'An toàn'}

7. DANH SÁCH DỮ LIỆU KHÁC:
- Nhà cung cấp: ${allSupplierNames || 'Trống'}
- Đội xe: ${vehicleList.length} xe (${maintenanceDue ? 'Cần bảo trì: ' + maintenanceDue : 'Ổn định'})
- Các bảng dữ liệu sẵn có: ${Object.keys(window.erp_raw_data || {}).join(', ')}
        `;
        } catch (e) {
            console.error('Error building AI context:', e);
            return 'Dữ liệu hệ thống đang được cập nhật...';
        }
    };

