    window.erpApp.viewAIDataDetail = function (type, id) {
        let title = 'Chi tiết định danh';
        let bodyHtml = '';

        if (type === 'product') {
            const item = danhSachHangHoaData.find(p => p.id === id) || danhSachHangHoaData[0];
            title = `Thông tin sản phẩm: ${item.id}`;
            bodyHtml = `
                <div style="display:flex; gap:20px; align-items:flex-start;">
                    <div style="width:120px; height:120px; background:#f1f5f9; border-radius:12px; display:flex; align-items:center; justify-content:center; flex-shrink:0;">
                        <span class="material-icons-outlined" style="font-size:60px; color:#cbd5e1;">inventory_2</span>
                    </div>
                    <div style="flex:1;">
                        <h4 style="font-size:18px; font-weight:800; color:#1e293b; margin-bottom:4px;">${item.name}</h4>
                        <div style="font-size:12px; color:#64748b; margin-bottom:12px;">Loại hàng: ${item.category} | Đơn vị: ${item.unit}</div>
                        
                        <div style="display:grid; grid-template-columns:1fr 1fr; gap:12px; margin-bottom:16px;">
                            <div style="background:#f8fafc; padding:10px; border-radius:8px;">
                                <div style="font-size:11px; color:#94a3b8; font-weight:600;">Giá bán niêm yết</div>
                                <div style="font-size:14px; font-weight:700; color:#4f46e5;">${window.erpApp.formatValue(item.price)} VND</div>
                            </div>
                            <div style="background:var(--icon-green-bg); padding:10px; border-radius:8px;">
                                <div style="font-size:11px; color:var(--icon-green); font-weight:600;">Tồn kho thực tế</div>
                                <div style="font-size:14px; font-weight:700; color:var(--icon-green);">125 ${item.unit}</div>
                            </div>
                        </div>
                        
                        <div style="padding:12px; background:#eff6ff; border:1px solid #dbeafe; border-radius:10px;">
                            <div style="display:flex; align-items:center; gap:8px; margin-bottom:4px;">
                                <span class="material-icons-outlined" style="font-size:16px; color:#3b82f6;">psychology</span>
                                <span style="font-size:12px; font-weight:700; color:#1e40af;">Ghi chú từ Trợ lý AI</span>
                            </div>
                            <div style="font-size:12px; color:#1e3a8a; line-height:1.5;">
                                Sản phẩm này có tỷ lệ quay vòng kho cao (92%). AI đề xuất duy trì mức tồn kho an toàn là 100 ${item.unit} do biến động thị trường.
                            </div>
                        </div>
                    </div>
                </div>
            `;
        } else if (type === 'order') {
            const order = salesOrders.find(s => s.id === id) || salesOrders[0];
            title = `Thông tin đơn hàng: ${order.id}`;
            bodyHtml = `
                    <div style="margin-bottom:20px;">
                        <div style="display:inline-block; padding:4px 12px; background:#f0f9ff; color:#3b82f6; border-radius:20px; font-size:12px; font-weight:700; margin-bottom:12px;">CHI TIẾT SO</div>
                        <h4 style="font-size:18px; font-weight:800; color:#1e293b; margin-bottom:4px;">${order.customer}</h4>
                        <div style="font-size:13px; color:#64748b;">Ngày đặt hàng: ${order.orderDate}</div>
                    </div>
                    
                    <table style="width:100%; border-collapse:collapse; margin-bottom:20px;">
                        <thead>
                            <tr style="border-bottom:2px solid #f1f5f9;">
                                <th style="text-align:left; padding:10px 0; font-size:12px; color:#94a3b8;">MẶT HÀNG</th>
                                <th style="text-align:center; padding:10px 0; font-size:12px; color:#94a3b8;">SỐ LƯỢNG</th>
                                <th style="text-align:right; padding:10px 0; font-size:12px; color:#94a3b8;">THÀNH TIỀN</th>
                            </tr>
                        </thead>
                        <tbody>
                            ${order.items.map(it => `
                                <tr style="border-bottom:1px solid #f1f5f9;">
                                    <td style="padding:12px 0; font-size:13px; font-weight:600;">${it.name}</td>
                                    <td style="padding:12px 0; font-size:13px; text-align:center;">${it.qty} ${it.unit}</td>
                                    <td style="padding:12px 0; font-size:13px; font-weight:700; text-align:right;">${window.erpApp.formatValue(it.price)}</td>
                                </tr>
                            `).join('')}
                        </tbody>
                        <tfoot>
                            <tr>
                                <td colspan="2" style="padding:12px 0; text-align:right; font-weight:600;">Tổng cộng:</td>
                                <td style="padding:12px 0; text-align:right; font-size:16px; font-weight:800; color:var(--primary);">${window.erpApp.formatValue(order.totalAmount)} VND</td>
                            </tr>
                        </tfoot>
                    </table>

                    <div style="padding:12px; background:#fffbeb; border:1px solid #fef3c7; border-radius:10px;">
                        <div style="display:flex; align-items:center; gap:8px; margin-bottom:4px;">
                            <span class="material-icons-outlined" style="font-size:16px; color:#f59e0b;">insights</span>
                            <span style="font-size:12px; font-weight:700; color:#92400e;">Phán đoán rủi ro AI</span>
                        </div>
                        <div style="font-size:12px; color:#78350f;">
                            Đơn hàng có giá trị cao bất thường đối với khách hàng này. AI khuyến nghị kiểm tra lại hạn mức tín dụng trước khi xuất kho.
                        </div>
                    </div>
            `;
        }

        const overlay = document.createElement('div');
        overlay.className = 'modal-overlay';
        overlay.innerHTML = `
            <div class="modal-content" style="max-width:600px; animation: modalIn 0.3s cubic-bezier(0.34, 1.56, 0.64, 1);">
                <div class="modal-header">
                    <h2 style="font-size:18px; font-weight:800; display:flex; align-items:center; gap:10px;">
                        <span class="material-icons-outlined" style="color:var(--primary);">smart_toy</span> ${title}
                    </h2>
                    <button class="modal-close" onclick="this.closest('.modal-overlay').remove()"><span class="material-icons-outlined">close</span></button>
                </div>
                <div class="modal-body" style="padding:24px;">
                    ${bodyHtml}
                </div>
                <div class="modal-footer" style="background:#f8fafc;">
                    <button class="btn-cancel" onclick="this.closest('.modal-overlay').remove()">Đóng</button>
                    <button class="btn-save" onclick="this.closest('.modal-overlay').remove(); window.erpApp.navigateTo('${type === 'product' ? 'kho-van' : 'kinh-doanh'}')">Đi tới phân hệ</button>
                </div>
            </div>
        `;
        document.body.appendChild(overlay);
    };


