    window.erpApp.closeSupplierModal = function () {
        const m = document.getElementById('supplierModal');
        if (m) { m.remove(); }
    };

    window.erpApp.saveSupplier = function (e) {
        e.preventDefault();
        const formData = new FormData(e.target);
        const data = Object.fromEntries(formData.entries());

        const index = suppliers.findIndex(c => c.id === data.id);
        if (index > -1) {
            suppliers[index] = { ...suppliers[index], ...data, rating: parseInt(data.rating) || 3 };
            showToast('Đã cập nhật HS Đối tác ' + data.id);
        } else {
            suppliers.unshift({ ...data, rating: parseInt(data.rating) || 3 });
            showToast('Đã thêm NCC mới!');
        }

        localStorage.setItem('erp_suppliers', JSON.stringify(suppliers));
        if (window.CrudSync) {
            const supplierData = index > -1 ? suppliers[index] : suppliers[0];
            window.CrudSync.saveItem('erp_suppliers', supplierData, 'id');
        }
        window.erpApp.closeSupplierModal();
        window.erpApp.renderNhaCungCap(supplierModuleContext);
    };

    window.erpApp.confirmDeleteSupplier = function (id) {
        const s = suppliers.find(x => x.id === id);
        const name = s ? s.name : id;
        const label = supplierModuleContext === 'Quản lý dự án' ? 'Đối tác' : 'Nhà cung cấp';

        const modalHtml = `
            <div class="modal-overlay" id="confirmDeleteModal" style="z-index: 9999;">
                <div class="modal-content" style="width: 400px; padding: 32px; text-align: center; border-radius: 24px; background: #fff; box-shadow: 0 20px 50px rgba(0,0,0,0.2);">
                    <div style="width: 72px; height: 72px; background: #fee2e2; color: #ef4444; border-radius: 50%; display: flex; align-items: center; justify-content: center; margin: 0 auto 24px; animation: pulseRed 2s infinite;">
                        <span class="material-icons-outlined" style="font-size: 36px;">delete_forever</span>
                    </div>
                    <style>
                        @keyframes pulseRed {
                            0% { box-shadow: 0 0 0 0 rgba(239, 68, 68, 0.4); }
                            70% { box-shadow: 0 0 0 15px rgba(239, 68, 68, 0); }
                            100% { box-shadow: 0 0 0 0 rgba(239, 68, 68, 0); }
                        }
                    </style>
                    <h3 style="margin: 0 0 12px; font-size: 20px; font-weight: 800; color: #1e293b;">Xác nhận xóa ${label}?</h3>
                    <p style="margin: 0 0 28px; color: #64748b; font-size: 14px; line-height: 1.6;">
                        Bạn có chắc chắn muốn xóa hồ sơ của <b>${name}</b>?<br>Hành động này sẽ xóa vĩnh viễn dữ liệu và không thể khôi phục.
                    </p>
                    <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 16px;">
                        <button onclick="document.getElementById('confirmDeleteModal').remove()" 
                            style="padding: 14px; border: 1px solid #e2e8f0; background: #fff; color: #64748b; border-radius: 14px; font-weight: 700; cursor: pointer; transition: all 0.2s;"
                            onmouseover="this.style.background='#f8fafc'" onmouseout="this.style.background='#fff'">
                            Hủy bỏ
                        </button>
                        <button id="btnConfirmDelete" 
                            style="padding: 14px; border: none; background: #ef4444; color: #fff; border-radius: 14px; font-weight: 700; cursor: pointer; box-shadow: 0 8px 20px rgba(239, 68, 68, 0.25); transition: all 0.2s;"
                            onmouseover="this.style.transform='translateY(-2px)'; this.style.boxShadow='0 10px 25px rgba(239, 68, 68, 0.3)';"
                            onmouseout="this.style.transform='translateY(0)'; this.style.boxShadow='0 8px 20px rgba(239, 68, 68, 0.25)';">
                            Xác nhận xóa
                        </button>
                    </div>
                </div>
            </div>
        `;
        document.body.insertAdjacentHTML('beforeend', modalHtml);

        document.getElementById('btnConfirmDelete').onclick = function () {
            const modal = document.getElementById('confirmDeleteModal');
            if (modal) { modal.remove(); }

            suppliers = suppliers.filter(c => c.id !== id);
            localStorage.setItem('erp_suppliers', JSON.stringify(suppliers));
            if (window.CrudSync) { window.CrudSync.deleteItem('erp_suppliers', id); }
            showToast('Đã xóa dữ liệu!');
            window.erpApp.renderNhaCungCap(supplierModuleContext);
        };
    };

    window.erpApp.supplierSearch = function (val) {
        supplierSearchQuery = val;
        window.erpApp.renderNhaCungCap(supplierModuleContext);
    };

    window.erpApp.supplierSetTab = function (tab) {
        supplierActiveTab = tab;
        window.erpApp.renderNhaCungCap(supplierModuleContext);
    };


    // ==========================================
    // MODULE: Yêu cầu báo giá (RFQ)
