    async function saveEmployee(e) {
        e.preventDefault();

        const editId = document.getElementById('empEditId').value;
        const avatarDataEl = document.getElementById('empAvatarData');
        const data = {
            name: document.getElementById('empName').value.trim(),
            gender: document.getElementById('empGender').value,
            dob: document.getElementById('empDob').value,
            cccd: document.getElementById('empCccd').value.trim(),
            phone: document.getElementById('empPhone').value.trim(),
            email: document.getElementById('empEmail').value.trim(),
            address: document.getElementById('empAddress').value.trim(),
            department: document.getElementById('empDepartment').value,
            position: document.getElementById('empPosition').value,
            joinDate: document.getElementById('empJoinDate').value,
            status: document.getElementById('empStatus').value,
            note: document.getElementById('empNote').value.trim()
        };

        // Xử lý avatar
        if (avatarDataEl && avatarDataEl.value === '__REMOVED__') {
            data.avatar = '';
        } else if (avatarDataEl && avatarDataEl.value && avatarDataEl.value !== '__REMOVED__') {
            data.avatar = avatarDataEl.value;
        }

        if (editId) {
            // Chỉnh sửa
            const idx = employees.findIndex(e => e.id === editId);
            if (idx !== -1) {
                employees[idx] = { ...employees[idx], ...data };
                if (window.CrudSync) { await window.CrudSync.saveItem('employees', employees[idx], 'id'); }

                // Đồng bộ sang profile nếu là tài khoản đang đăng nhập
                const currentProfile = window.getProfileData ? window.getProfileData() : null;
                if (currentProfile && currentProfile.employeeId === editId) {
                    const newProfile = {
                        ...currentProfile,
                        fullName: data.name,
                        phone: data.phone,
                        department: data.department,
                        role: data.position,
                        emailWork: data.email,
                        avatar: data.avatar || currentProfile.avatar
                    };
                    window.saveProfileData(newProfile);
                }
            }
            window.erpApp.notifyCRUD('Nhân sự', 'update', {
                name: data.name,
                page: 'hanh-chinh',
                module: 'Hồ sơ nhân viên'
            });
        } else {
            // Thêm mới
            const newId = nextEmployeeId();
            const newEmp = { id: newId, ...data };
            employees.push(newEmp);
            if (window.CrudSync) { await window.CrudSync.saveItem('employees', newEmp, 'id'); }
            window.erpApp.notifyCRUD('Nhân sự', 'add', {
                name: data.name,
                page: 'hanh-chinh',
                module: 'Hồ sơ nhân viên'
            });
        }
        localStorage.setItem('erp_employees', JSON.stringify(employees));
        closeEmpModal();
        renderHoSoNhanVien();
    }

