    // --- Xác nhận xóa ---
    function confirmDeleteEmployee(id) {
        const emp = employees.find(e => e.id === id);
        if (!emp) { return; }

        window.erpApp.showDeleteConfirmation(
            `Bạn có chắc chắn muốn xóa nhân viên <span class="confirm-name">${emp.name}</span> (${emp.id}) khỏi hệ thống? Hành động này không thể hoàn tác.`,
            () => deleteEmployee(id)
        );
    }

    function deleteEmployee(id) {
        const emp = employees.find(e => e.id === id);
        employees = employees.filter(e => e.id !== id);
        if (window.CrudSync) { window.CrudSync.deleteItem('employees', id); }
        localStorage.setItem('erp_employees', JSON.stringify(employees));
        renderHoSoNhanVien();
        showToast(`Đã xóa nhân viên: ${emp ? emp.name : id}`, 'success');

        // Gửi thông báo hệ thống (Audit Log)
        window.erpApp.notifyCRUD('Nhân sự', 'delete', {
            name: emp ? emp.name : id,
            page: 'hanh-chinh',
            module: 'Hồ sơ nhân viên'
        });
    }

