    // --- Xóa hợp đồng ---
    function confirmDeleteContract(id) {
        const ct = contracts.find(c => c.id === id);
        if (!ct) { return; }

        window.erpApp.showDeleteConfirmation(
            `Bạn có chắc chắn muốn xóa hợp đồng <span class="confirm-name">${ct.id}</span> của ${ct.empName}? Hành động này không thể hoàn tác.`,
            () => deleteContract(id)
        );
    }

    function deleteContract(id) {
        const ct = contracts.find(c => c.id === id);
        contracts = contracts.filter(c => c.id !== id);
        if (window.CrudSync) { window.CrudSync.deleteItem('contracts', id); }
        localStorage.setItem('erp_contracts', JSON.stringify(contracts));
        renderHopDongLaoDong();
        showToast(`Đã xóa hợp đồng: ${ct ? ct.id : id}`, 'success');

        window.erpApp.notifyCRUD('Hợp đồng', 'delete', {
            name: ct ? ct.empName : id,
            page: 'hanh-chinh',
            module: 'Hợp đồng lao động'
        });
    }

