    window.erpApp.pkFilterWh = (w) => { pkFilterWarehouse = w; pkCurrentPage = 1; renderPhieuKho(); };
    window.erpApp.pkSearch = (q) => { pkSearchQuery = q; pkCurrentPage = 1; renderPhieuKho(); };
    window.erpApp.pkGoPage = (p) => { pkCurrentPage = p; renderPhieuKho(); };
