    window.erpApp.deletePhieuKho = deletePhieuKho;
    window.erpApp.closePkDeleteModal = closePkDeleteModal;
    window.erpApp.printPk = printPk;

    window.erpApp.addPkItem = () => {
        tempPkItems.push({ name: '', qty: 1, unit: '', price: 0 });
        const list = document.getElementById('pkItemsList');
        if (list) { list.innerHTML = renderPkItemsList(); }
    };
    window.erpApp.removePkItem = (i) => {
        tempPkItems.splice(i, 1);
        const list = document.getElementById('pkItemsList');
        if (list) { list.innerHTML = renderPkItemsList(); }
    };
    window.erpApp.updatePkItem = (i, field, val) => {
        tempPkItems[i][field] = val;
    };
    window.erpApp.handlePkFileUpload = (e) => {
        const files = e.target.files;
        if (!files) { return; }
        for (let i = 0; i < files.length; i++) {
            const f = files[i];
            const reader = new FileReader();
            reader.onload = (ex) => {
                tempPkFiles.push({ name: f.name, type: f.type, size: f.size, data: ex.target.result, date: new Date().toLocaleString('vi-VN') });
                const list = document.getElementById('pkFileList');
                if (list) { list.innerHTML = window.erpApp.renderHsFileList(tempPkFiles, true, 'pk-edit'); }
            };
            reader.readAsDataURL(f);
        }
    };
    window.erpApp.handlePkTypeChange = (val) => {
        const toWh = document.getElementById('groupPkToWarehouse');
        if (toWh) { toWh.style.display = (val === 'chuyen' ? 'block' : 'none'); }
    };

    async function savePhieuKho() {
        if (!isAdmin()) { showToast('Bạn không có quyền thực hiện chức năng này!', 'error'); return; }
        const id = document.getElementById('pkEditId').value;
        const type = document.getElementById('pkType').value;
        const date = document.getElementById('pkDate').value;
        const warehouse = document.getElementById('pkWarehouse').value;
        const partner = document.getElementById('pkPartner').value;
        const sender = document.getElementById('pkSender').value.trim();
        const receiver = document.getElementById('pkReceiver').value.trim();
        const responsible = document.getElementById('pkResponsible').value;
        const status = document.getElementById('pkStatus').value;
        const desc = document.getElementById('pkDesc').value.trim();
        // Get first URL for backward compatibility
        const firstFile = (window.tempContractFiles && window.tempContractFiles.length > 0) ? window.tempContractFiles[0] : null;
        const fileUrl = firstFile ? (firstFile.url || firstFile.dataUrl || '') : '';

        if (!date || !warehouse) { showToast('Vui lòng điền đầy đủ thông tin!'); return; }

        const now = new Date();
        const updatedAt = String(now.getMonth() + 1).padStart(2, '0') + '/' + String(now.getDate()).padStart(2, '0');

        const pkData = {
            date, warehouse, partner, sender, receiver, responsible, status, desc, updatedAt, fileUrl,
            files: [...window.tempContractFiles],
            items: [...tempPkItems]
        };

        if (id) {
            const pk = pkList.find(p => p.id === id);
            if (pk) {
                Object.assign(pk, pkData);
                if (window.FileStore) { await window.FileStore.saveAllFiles('pkList', pk.id, pk.files); }
                if (window.CrudSync) { await window.CrudSync.saveItem('pkList', pk, 'id'); }
                showToast('Đã cập nhật ' + id);
            }
        } else {
            const newPk = { id: nextPkId(type), type, ...pkData };
            pkList.unshift(newPk);
            if (window.FileStore) { await window.FileStore.saveAllFiles('pkList', newPk.id, newPk.files); }
            if (window.CrudSync) { await window.CrudSync.saveItem('pkList', newPk, 'id'); }
            showToast('Đã thêm phiếu mới');
        }
        closePkEditModal(); renderPhieuKho();
    }

    function confirmDeletePk(id) {
        const pk = pkList.find(p => p.id === id); if (!pk) { return; }
        const modal = document.createElement('div'); modal.className = 'modal-overlay'; modal.id = 'pkDeleteModal';
        modal.innerHTML = `<div class="modal-content" style="max-width:420px"><div class="modal-header"><h3><span class="material-icons-outlined" style="color:#DC2626">warning</span> Xác nhận xóa</h3><button class="modal-close" onclick="window.erpApp.closePkDeleteModal()"><span class="material-icons-outlined">close</span></button></div>
            <div class="modal-body" style="text-align:center;padding:24px"><p style="font-size:15px">Xóa phiếu <strong>${pk.id}</strong>?</p><p style="color:var(--text-secondary);margin-top:8px;font-size:13px">${pk.desc}</p></div>
            <div class="modal-footer"><button class="btn-cancel" onclick="window.erpApp.closePkDeleteModal()">Hủy</button><button class="btn-save" style="background:#DC2626" onclick="window.erpApp.deletePhieuKho('${pk.id}')"><span class="material-icons-outlined">delete</span> Xóa</button></div></div>`;
        document.body.appendChild(modal);
    }
    function deletePhieuKho(id) {
        if (!isAdmin()) { showToast('Bạn không có quyền thực hiện chức năng này!', 'error'); return; }
        pkList = pkList.filter(p => p.id !== id);
        const m = document.getElementById('pkDeleteModal');
        if (m) { m.classList.add('closing'); setTimeout(() => m.remove(), 200); }
        showToast('Đã xóa ' + id); renderPhieuKho();
    }
    function closePkDeleteModal() { const m = document.getElementById('pkDeleteModal'); if (m) { m.classList.add('closing'); setTimeout(() => m.remove(), 200); } }

    function printPk(id) {
        const pk = pkList.find(p => p.id === id); if (!pk) { return; }
        const printWindow = window.open('', '_blank');
        const itemsHtml = pk.items && pk.items.length > 0 ? pk.items.map((it, i) => `
            <tr>
                <td style="border:1px solid #000;padding:8px;text-align:center">${i + 1}</td>
                <td style="border:1px solid #000;padding:8px">${it.name}</td>
                <td style="border:1px solid #000;padding:8px;text-align:center">${it.unit}</td>
                <td style="border:1px solid #000;padding:8px;text-align:right">${it.qty}</td>
                <td style="border:1px solid #000;padding:8px;text-align:right">${(it.price || 0).toLocaleString('vi-VN')}</td>
                <td style="border:1px solid #000;padding:8px;text-align:right">${((it.qty || 0) * (it.price || 0)).toLocaleString('vi-VN')}</td>
            </tr>
        `).join('') : '<tr><td colspan="6" style="text-align:center;padding:20px;border:1px solid #000">Không có dữ liệu hàng hóa</td></tr>';

        const total = pk.items ? pk.items.reduce((s, it) => s + (it.qty || 0) * (it.price || 0), 0) : 0;

        printWindow.document.write(`
            <html>
            <head>
                <title>In Phiếu Kho - ${pk.id}</title>
                <style>
                    body { font-family: 'Inter', sans-serif; padding: 40px; color: #000; }
                    .header { display: flex; justify-content: space-between; margin-bottom: 30px; }
                    .company-info h2 { margin: 0; font-size: 20px; text-transform: uppercase; }
                    .company-info p { margin: 4px 0; font-size: 14px; }
                    .title { text-align: center; margin-bottom: 20px; }
                    .title h1 { margin: 0; font-size: 24px; text-transform: uppercase; }
                    .title p { margin: 5px 0; font-style: italic; }
                    .info-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; margin-bottom: 20px; font-size: 15px; }
                    table { width: 100%; border-collapse: collapse; margin-bottom: 30px; }
                    th { background: #f2f2f2; border: 1px solid #000; padding: 8px; font-weight: bold; }
                    .footer-sig { display: grid; grid-template-columns: 1fr 1fr 1fr 1fr; gap: 10px; text-align: center; margin-top: 40px; }
                    .sig-box { height: 100px; }
                    @media print { .no-print { display: none; } }
                </style>
            </head>
            <body>
                <div class="header">
                    <div class="company-info">
                        <h2>CÔNG TY CỔ PHẦN VIỆT BÁCH</h2>
                        <p>Địa chỉ: KCN Hòn Đất, Kiên Giang</p>
                        <p>Điện thoại: 0297.xxxx.xxx</p>
                    </div>
                </div>
                <div class="title">
                    <h1>PHIẾU ${getPkTabLabel(pk.type).toUpperCase()} KHO</h1>
                    <p>Ngày: ${formatDate(pk.date)}</p>
                    <p>Số: <strong>${pk.id}</strong></p>
                </div>
                <div class="info-grid">
                    <div>Người giao: <strong>${pk.sender || '—'}</strong></div>
                    <div>Người nhận: <strong>${pk.receiver || '—'}</strong></div>
                    <div>Kho: <strong>${pk.warehouse}</strong></div>
                    <div>Đối tác: <strong>${pk.partner || '—'}</strong></div>
                    <div style="grid-column: span 2">Lý do/Mô tả: ${pk.desc || '—'}</div>
                </div>
                <table>
                    <thead>
                        <tr>
                            <th style="width:40px">STT</th>
                            <th>Tên hàng hóa, quy cách</th>
                            <th style="width:80px">ĐVT</th>
                            <th style="width:80px">Số lượng</th>
                            <th style="width:100px">Đơn giá</th>
                            <th style="width:120px">Thành tiền</th>
                        </tr>
                    </thead>
                    <tbody>
                        ${itemsHtml}
                        <tr style="font-weight:bold">
                            <td colspan="5" style="border:1px solid #000;padding:8px;text-align:right">Tổng cộng:</td>
                            <td style="border:1px solid #000;padding:8px;text-align:right">${total.toLocaleString('vi-VN')}đ</td>
                        </tr>
                    </tbody>
                </table>
                <div style="font-style:italic; margin-bottom:20px">Tổng số tiền (bằng chữ): .................................................................................................................</div>
                <div class="footer-sig">
                    <div><strong>Người lập phiếu</strong><br>(Ký, họ tên)<div class="sig-box"></div><strong>${pk.responsible || ''}</strong></div>
                    <div><strong>Người giao hàng</strong><br>(Ký, họ tên)<div class="sig-box"></div></div>
                    <div><strong>Thủ kho</strong><br>(Ký, họ tên)<div class="sig-box"></div></div>
                    <div><strong>Người nhận hàng</strong><br>(Ký, họ tên)<div class="sig-box"></div></div>
                </div>
                <div style="margin-top:50px; text-align:right; font-size:12px" class="no-print">
                    <button onclick="window.print()" style="padding:10px 20px; background:#4f46e5; color:#fff; border:none; border-radius:6px; cursor:pointer">Bắt đầu in</button>
                </div>
            </body>
            </html>
        `);
        printWindow.document.close();
    }

