    function getKkStatusLabel(status) {
        switch (status) {
            case 'completed': return 'Hoàn thành';
            case 'processing': return 'Đang kiểm kê';
            case 'draft': return 'Nháp';
            default: return status;
        }
    }

    function getKkStatusColor(status) {
        switch (status) {
            case 'completed': return 'green';
            case 'processing': return 'orange';
            case 'draft': return 'gray';
            default: return 'blue';
        }
    }

    function getKkStatusIcon(status) {
        switch (status) {
            case 'completed': return 'check_circle';
            case 'processing': return 'sync';
            case 'draft': return 'description';
            default: return 'info';
        }
    }
    // ==========================================
    // MODULE: Danh mục hàng hóa (Hierarchical)
    // ==========================================
    let dmhhSearchTimeout;
    window.erpApp.dmhhSearch = function (val) {
        dmhhSearchQuery = val.toLowerCase();
        clearTimeout(dmhhSearchTimeout);
        dmhhSearchTimeout = setTimeout(() => {
            window.erpApp.renderDanhMucHangHoa();
        }, 150);
    };

    // Helper to get category name from ID
    window.erpApp.getCategoryLabel = function (catId) {
        if (!catId || catId === 'all') { return 'Tất cả'; }
        const mapping = {
            '2-1': 'Vật tư văn phòng',
            '1-1': 'Vật liệu Xây dựng',
            '1-2': 'Nguyên liệu SX',
            '1': 'Vật liệu khác'
        };
        if (mapping[catId]) { return mapping[catId]; }

        const catLookup = (window.erpApp.danhMucHangHoaData || danhMucHangHoaData || []).find(c => c.id === catId);
        return catLookup ? catLookup.name : catId;
    };



