    window.erpApp.openDskModal = function (id = null) {
        const isEdit = !!id;
        const item = isEdit ? danhSachKhoData.find(d => d.id === id) : null;
        let selectedManager = isEdit ? item.manager : '';

        const empList = window.erpApp.getEmployees();
        let managerOptions = empList.map(emp =>
            `<option value="${emp.id}" ${selectedManager == emp.id ? 'selected' : ''}>${emp.id} - ${emp.name} (${emp.position})</option>`
        ).join('');

        const modal = document.createElement('div');
        modal.className = 'modal-overlay';
        modal.id = 'dskModal';
        modal.innerHTML = `
            <div class="modal-content" style="max-width: 600px; background: #fff; padding: 0; border-radius: 12px; overflow: hidden; box-shadow: 0 10px 25px rgba(0,0,0,0.1);">
                <div class="modal-header" style="padding: 16px 24px; border-bottom: 1px solid var(--border-color); display: flex; justify-content: space-between; align-items: center; background: #F8FAFC;">
                    <h3 style="margin: 0; font-size: 18px; font-weight: 700; color: var(--text-main); display: flex; align-items: center; gap: 8px;">
                        <span class="material-icons-outlined" style="color: var(--primary);">store</span>
                        ${isEdit ? 'Chỉnh sửa thông tin kho' : 'Thêm mới kho'}
                    </h3>
                    <button onclick="window.erpApp.closeDskModal()" style="background: none; border: none; cursor: pointer; color: var(--text-muted);"><span class="material-icons-outlined">close</span></button>
                </div>
                <div class="modal-body" style="padding: 24px; max-height: 70vh; overflow-y: auto;">
                    <input type="hidden" id="dskOldId" value="${isEdit ? item.id : ''}">
                    
                    <div style="display: grid; grid-template-columns: 1fr 2fr; gap: 16px; margin-bottom: 16px;">
                        <div>
                            <label style="display: block; font-size: 13px; font-weight: 600; margin-bottom: 6px; color: var(--text-secondary);">Mã kho <span style="color: #EF4444;">*</span></label>
                            <input type="text" id="dskId" value="${isEdit ? item.id : ''}" ${isEdit ? 'readonly' : ''} placeholder="VD: K-HD" style="width: 100%; padding: 10px 14px; border: 1px solid var(--border-color); border-radius: 8px; font-size: 14px; ${isEdit ? 'background: #F1F5F9;' : ''}">
                        </div>
                        <div>
                            <label style="display: block; font-size: 13px; font-weight: 600; margin-bottom: 6px; color: var(--text-secondary);">Tên kho <span style="color: #EF4444;">*</span></label>
                            <input type="text" id="dskName" value="${isEdit ? item.name : ''}" placeholder="VD: Kho Hòn Đất" style="width: 100%; padding: 10px 14px; border: 1px solid var(--border-color); border-radius: 8px; font-size: 14px;">
                        </div>
                    </div>

                    <div style="margin-bottom: 16px;">
                        <label style="display: block; font-size: 13px; font-weight: 600; margin-bottom: 6px; color: var(--text-secondary);">Địa chỉ / Vị trí</label>
                        <input type="text" id="dskLocation" value="${isEdit ? (item.location || '') : ''}" placeholder="Số nhà, đường, tỉnh/thành..." style="width: 100%; padding: 10px 14px; border: 1px solid var(--border-color); border-radius: 8px; font-size: 14px;">
                    </div>

                    <div style="display: grid; grid-template-columns: 2fr 1fr; gap: 16px; margin-bottom: 16px;">
                        <div>
                            <label style="display: block; font-size: 13px; font-weight: 600; margin-bottom: 6px; color: var(--text-secondary);">Người phụ trách</label>
                            <select id="dskManager" style="width: 100%; padding: 10px 14px; border: 1px solid var(--border-color); border-radius: 8px; font-size: 14px; background: #fff;">
                                <option value="">— Chọn người phụ trách —</option>
                                ${managerOptions}
                            </select>
                        </div>
                        <div>
                            <label style="display: block; font-size: 13px; font-weight: 600; margin-bottom: 6px; color: var(--text-secondary);">Số ĐT liên hệ</label>
                            <input type="text" id="dskPhone" value="${isEdit ? (item.phone || '') : ''}" placeholder="VD: 0909..." style="width: 100%; padding: 10px 14px; border: 1px solid var(--border-color); border-radius: 8px; font-size: 14px;">
                        </div>
                    </div>

                    <div style="margin-bottom: 16px;">
                        <label style="display: block; font-size: 13px; font-weight: 600; margin-bottom: 6px; color: var(--text-secondary);">Trạng thái</label>
                        <select id="dskStatus" style="width: 100%; padding: 10px 14px; border: 1px solid var(--border-color); border-radius: 8px; font-size: 14px; background: #fff;">
                            <option value="active" ${isEdit && item.status === 'active' ? 'selected' : ''}>Hoạt động</option>
                            <option value="inactive" ${isEdit && item.status === 'inactive' ? 'selected' : ''}>Tạm ngưng</option>
                            <option value="rental" ${isEdit && item.status === 'rental' ? 'selected' : ''}>Cho Thuê</option>
                        </select>
                    </div>

                    <div style="margin-bottom: 16px;">
                        <label style="display: block; font-size: 13px; font-weight: 600; margin-bottom: 6px; color: var(--text-secondary);">Ghi chú</label>
                        <textarea id="dskDesc" style="width: 100%; padding: 10px 14px; border: 1px solid var(--border-color); border-radius: 8px; font-size: 14px; resize: vertical; min-height: 80px;">${isEdit ? (item.desc || '') : ''}</textarea>
                    </div>
                </div>
                <div class="modal-footer" style="padding: 16px 24px; border-top: 1px solid var(--border-color); display: flex; justify-content: flex-end; gap: 12px; background: #F8FAFC;">
                    <button class="btn-cancel" onclick="window.erpApp.closeDskModal()" style="padding: 10px 20px; border: 1px solid var(--border-color); border-radius: 8px; background: #fff; cursor: pointer; font-weight: 600;">Hủy</button>
                    ${isAdmin() ? `
                    <button class="btn-save" onclick="window.erpApp.saveDsk()" style="padding: 10px 20px; border: none; border-radius: 8px; background: var(--primary); color: #fff; cursor: pointer; font-weight: 600; box-shadow: 0 4px 12px rgba(37,99,235,0.2);"><span class="material-icons-outlined" style="font-size: 18px; vertical-align: middle; margin-right: 4px;">save</span>Lưu lại</button>
                    ` : ''}
                </div>
            </div>
        `;
        document.body.appendChild(modal);
    };

    window.erpApp.closeDskModal = function () {
        const modal = document.getElementById('dskModal');
        if (modal) {
            modal.classList.add('closing');
            setTimeout(() => modal.remove(), 200);
        }
    };

    window.erpApp.saveDsk = function () {
        if (!isAdmin()) { showToast('Bạn không có quyền thực hiện chức năng này!', 'error'); return; }
        const isEdit = !!document.getElementById('dskOldId').value;
        const id = document.getElementById('dskId').value.trim();
        const name = document.getElementById('dskName').value.trim();
        const location = document.getElementById('dskLocation').value.trim();
        const manager = document.getElementById('dskManager').value;
        const phone = document.getElementById('dskPhone').value.trim();
        const status = document.getElementById('dskStatus').value;
        const desc = document.getElementById('dskDesc').value.trim();

        if (!id || !name) {
            showToast('Mã kho và Tên kho không được để trống.', 'error');
            return;
        }

        const dateStr = new Date().toLocaleDateString('vi-VN');

        if (isEdit) {
            let item = danhSachKhoData.find(d => d.id === id);
            if (item) {
                item.name = name;
                item.location = location;
                item.manager = manager;
                item.phone = phone;
                item.status = status;
                item.desc = desc;
                item.updated = dateStr;
            }
        } else {
            if (danhSachKhoData.find(d => d.id === id)) {
                showToast('Mã kho đã tồn tại.', 'error');
                return;
            }
            danhSachKhoData.push({ id, name, location, manager, phone, status, desc, updated: dateStr });
        }

        const itemData = isEdit ? danhSachKhoData.find(d => d.id === id) : danhSachKhoData[danhSachKhoData.length - 1];
        localStorage.setItem('erp_danhSachKhoData', JSON.stringify(danhSachKhoData));
        if (window.CrudSync) { window.CrudSync.saveItem('danhSachKhoData', itemData, 'id'); }

        window.erpApp.notifyCRUD('Kho', isEdit ? 'update' : 'add', {
            name: name,
            id: id,
            page: 'kho-van',
            module: 'Danh sách kho'
        });

        window.erpApp.closeDskModal();
        window.erpApp.renderDanhSachKho();
        showToast(isEdit ? 'Cập nhật thành công' : 'Thêm kho thành công');

        // Add dynamic notification
        window.erpApp.addNotification(
            `${isEdit ? 'Cập nhật' : 'Thêm mới'} kho: ${name}`,
            'store',
            'green',
            { page: 'kho-van', module: DSK_TITLE, itemId: id }
        );
    };

    window.erpApp.deleteDsk = function (id) {
        if (!isAdmin()) { showToast('Bạn không có quyền thực hiện chức năng này!', 'error'); return; }
        const item = danhSachKhoData.find(d => d.id === id);
        window.erpApp.showConfirm(
            'Xác nhận xóa kho',
            `Bạn có chắc muốn xóa kho <strong>${id}</strong>?`,
            function () {
                danhSachKhoData = danhSachKhoData.filter(d => d.id !== id);
                localStorage.setItem('erp_danhSachKhoData', JSON.stringify(danhSachKhoData));
                if (window.CrudSync) { window.CrudSync.deleteItem('danhSachKhoData', id); }

                window.erpApp.notifyCRUD('Kho', 'delete', {
                    name: item ? item.name : id,
                    id: id,
                    page: 'kho-van',
                    module: 'Danh sách kho'
                });

                window.erpApp.renderDanhSachKho();
                showToast('Đã xóa kho');
            }
        );
    };

