    window.erpApp.closeDsdtModal = function () {
        const modal = document.getElementById('dsdtModal');
        if (modal) {
            modal.classList.add('closing');
            setTimeout(() => modal.remove(), 200);
        }
    };

    window.erpApp.saveDsdt = function () {
        if (!isAdmin()) { showToast('Bạn không có quyền thực hiện chức năng này!', 'error'); return; }
        const isEdit = !!document.getElementById('dsdtOldId').value;
        const id = document.getElementById('dsdtId').value.trim();
        const name = document.getElementById('dsdtName').value.trim();
        const group = document.getElementById('dsdtGroup').value;
        const taxId = document.getElementById('dsdtTaxId').value.trim();
        const address = document.getElementById('dsdtAddress').value.trim();
        const phone = document.getElementById('dsdtPhone').value.trim();
        const bankAccount = document.getElementById('dsdtBankAccount').value.trim();
        const status = document.getElementById('dsdtStatus').value;

        if (!id || !name) {
            showToast('Mã và Tên đối tác không được để trống.', 'error');
            return;
        }

        const dateStr = new Date().toLocaleDateString('vi-VN').substring(0, 5);

        if (isEdit) {
            let item = danhSachDoiTacData.find(d => d.id === id);
            if (item) {
                Object.assign(item, { name, group, taxId, address, phone, bankAccount, status, updated: dateStr });
            }
        } else {
            if (danhSachDoiTacData.find(d => d.id === id)) {
                showToast('Mã đối tác đã tồn tại.', 'error');
                return;
            }
            danhSachDoiTacData.push({ id, name, group, taxId, address, phone, bankAccount, status, updated: dateStr });
        }

        const itemData = isEdit ? danhSachDoiTacData.find(d => d.id === id) : danhSachDoiTacData[danhSachDoiTacData.length - 1];
        localStorage.setItem('erp_danhSachDoiTacData', JSON.stringify(danhSachDoiTacData));
        if (window.CrudSync) { window.CrudSync.saveItem('danhSachDoiTacData', itemData, 'id'); }

        window.erpApp.notifyCRUD('Đối tác', isEdit ? 'update' : 'add', {
            name: name,
            id: id,
            page: 'mua-hang',
            module: 'Danh sách đối tác'
        });

        window.erpApp.closeDsdtModal();
        window.erpApp.renderDanhSachDoiTac();
        showToast(isEdit ? 'Cập nhật thành công' : 'Thêm mới thành công');
    };

    window.erpApp.deleteDsdt = function (id) {
        if (!isAdmin()) { showToast('Bạn không có quyền thực hiện chức năng này!', 'error'); return; }
        const item = danhSachDoiTacData.find(d => d.id === id);
        window.erpApp.showConfirm(
            'Xác nhận xóa đối tác',
            `Bạn có chắc muốn xóa đối tác <strong>${id}</strong>?`,
            function () {
                danhSachDoiTacData = danhSachDoiTacData.filter(d => d.id !== id);
                localStorage.setItem('erp_danhSachDoiTacData', JSON.stringify(danhSachDoiTacData));
                if (window.CrudSync) { window.CrudSync.deleteItem('danhSachDoiTacData', id); }

                window.erpApp.notifyCRUD('Đối tác', 'delete', {
                    name: item ? item.name : id,
                    id: id,
                    page: 'mua-hang',
                    module: 'Danh sách đối tác'
                });

                window.erpApp.renderDanhSachDoiTac();
                showToast('Đã xóa đối tác');
            }
        );
    };


