        addCvFileLink: () => {
            const urlEl = document.getElementById('cvFileUrl');
            const nameEl = document.getElementById('cvFileUrlName');
            const urlVal = urlEl ? urlEl.value.trim() : '';
            const nameVal = nameEl ? nameEl.value.trim() : '';
            if (!urlVal) { showToast('Vui lòng nhập đường link!', 'error'); return; }
            const lines = urlVal.split('\n').filter(l => l.trim());
            const invalid = [];
            lines.forEach(line => {
                let [url, label] = line.split('|').map(s => s.trim());
                if (!label) { label = nameVal; }
                if (!url.startsWith('http')) { invalid.push(url); return; }
                const parsedName = label || url.replace(/\/+$|\?.*$/g, '').split('/').pop() || 'File liên kết';
                tempCvFiles.push({ name: parsedName, size: 'Link', type: 'link', url });
            });
            if (invalid.length) { showToast(`Bỏ qua link không hợp lệ: ${invalid.join(', ')}`, 'warning'); }
            if (urlEl) { urlEl.value = ''; }
            if (nameEl) { nameEl.value = ''; }
            const listEl = document.getElementById('cvFileList');
            if (listEl) { listEl.innerHTML = window.erpApp.renderHsFileList(tempCvFiles, true, 'cv-edit'); }
        },
