            localStorage.setItem('erp_pmAttendanceYear', pmAttendanceYear);
            localStorage.setItem('erp_pmAttendanceWeek', pmAttendanceWeek);
            localStorage.setItem('erp_pmAttendanceMode', 'month');

            // Sync
            window.pmAttendanceMonth = window.erpApp.pmAttendanceMonth = pmAttendanceMonth;
            window.pmAttendanceYear = window.erpApp.pmAttendanceYear = pmAttendanceYear;
            window.pmAttendanceWeek = window.erpApp.pmAttendanceWeek = pmAttendanceWeek;
